 52→/// Timeout for network I/O in filesystem callbacks to prevent blocking the mount thread.
 53→#[cfg(any(feature = "fuse", feature = "winfsp"))]
 54→const NETWORK_TIMEOUT: Duration = Duration::from_secs(10);
 55→
 56→/// Run an async future with a timeout on the tokio runtime.
 57→/// Prevents filesystem thread hangs from indefinite network I/O.
 58→#[cfg(any(feature = "fuse", feature = "winfsp"))]
 59→fn block_with_timeout<F, T>(rt: &tokio::runtime::Handle, fut: F) -> Result<T, String>
 60→where
 61→    F: std::future::Future<Output = Result<T, String>>,
 62→{
 63→    rt.block_on(async {
 64→        match tokio::time::timeout(NETWORK_TIMEOUT, fut).await {
 65→            Ok(result) => result,
 66→            Err(_) => Err("Operation timed out".to_string()),
 67→        }
 68→    })
 69→}
