107→/// Coordinates IPNS publish operations to prevent sequence number races.
108→#[cfg(any(feature = "fuse", feature = "winfsp"))]
109→pub struct PublishCoordinator {
110→    seq_cache: std::sync::Mutex<HashMap<String, u64>>,
111→    publish_locks: std::sync::Mutex<HashMap<String, Arc<tokio::sync::Mutex<()>>>>,
112→}
113→
114→#[cfg(any(feature = "fuse", feature = "winfsp"))]
115→impl PublishCoordinator {
116→    pub fn new() -> Self {
117→        Self {
118→            seq_cache: std::sync::Mutex::new(HashMap::new()),
119→            publish_locks: std::sync::Mutex::new(HashMap::new()),
120→        }
121→    }
122→
123→    pub fn get_lock(&self, ipns_name: &str) -> Arc<tokio::sync::Mutex<()>> {
124→        let mut locks = self.publish_locks.lock().unwrap();
125→        locks
126→            .entry(ipns_name.to_string())
127→            .or_insert_with(|| Arc::new(tokio::sync::Mutex::new(())))
128→            .clone()
129→    }
130→
131→    pub async fn resolve_sequence(
132→        &self,
133→        api: &cipherbox_api_client::ApiClient,
134→        ipns_name: &str,
135→    ) -> Result<u64, String> {
136→        match cipherbox_api_client::ipns::resolve_ipns(api, ipns_name).await {
137→            Ok(resp) => {
138→                let resolved = resp.sequence_number.parse::<u64>().unwrap_or_else(|e| {
139→                    log::warn!("Failed to parse IPNS sequence '{}' for {}: {}", resp.sequence_number, ipns_name, e);
140→                    0
141→                });
142→                let cached = self.get_cached(ipns_name).unwrap_or(0);
143→                let seq = std::cmp::max(resolved, cached);
144→                self.update_cache(ipns_name, seq);
145→                Ok(seq)
146→            }
147→            Err(e) => match self.get_cached(ipns_name) {
148→                Some(cached) => {
149→                    log::warn!("IPNS resolve failed for {}, using cached seq {}: {}", ipns_name, cached, e);
150→                    Ok(cached)
151→                }
152→                None => Err(format!("IPNS resolve failed and no cached sequence for {}: {}", ipns_name, e)),
153→            },
154→        }
155→    }
156→
157→    pub fn record_publish(&self, ipns_name: &str, published_seq: u64) {
158→        self.update_cache(ipns_name, published_seq);
159→    }
160→
161→    fn get_cached(&self, ipns_name: &str) -> Option<u64> {
162→        self.seq_cache.lock().unwrap().get(ipns_name).copied()
163→    }
164→
165→    fn update_cache(&self, ipns_name: &str, seq: u64) {
166→        let mut cache = self.seq_cache.lock().unwrap();
167→        let entry = cache.entry(ipns_name.to_string()).or_insert(0);
168→        if seq > *entry {
169→            *entry = seq;
170→        }
171→    }
172→}
