174→/// Encrypt a FolderMetadata struct and package as JSON bytes ready for IPFS upload.
175→#[cfg(any(feature = "fuse", feature = "winfsp"))]
176→pub fn encrypt_metadata_to_json(
177→    metadata: &cipherbox_core::folder::FolderMetadata,
178→    folder_key: &[u8],
179→) -> Result<Vec<u8>, String> {
180→    let folder_key_arr: [u8; 32] = folder_key
181→        .try_into()
182→        .map_err(|_| "Invalid folder key length".to_string())?;
183→    let sealed = cipherbox_core::folder::encrypt_folder_metadata(metadata, &folder_key_arr)
184→        .map_err(|e| format!("Metadata encryption failed: {}", e))?;
185→    let iv_hex = hex::encode(&sealed[..12]);
186→    use base64::Engine;
187→    let data_base64 = base64::engine::general_purpose::STANDARD.encode(&sealed[12..]);
188→    let json = serde_json::json!({ "iv": iv_hex, "data": data_base64 });
189→    serde_json::to_vec(&json).map_err(|e| format!("JSON serialization failed: {}", e))
190→}
