192→/// Merge local children onto remote children to resolve a concurrent-edit conflict.
193→#[cfg(any(feature = "fuse", feature = "winfsp"))]
194→pub fn merge_folder_children(
195→    local: &cipherbox_core::folder::FolderMetadata,
196→    remote: cipherbox_core::folder::FolderMetadata,
197→) -> cipherbox_core::folder::FolderMetadata {
198→    use cipherbox_core::folder::FolderChild;
199→
200→    fn child_ipns_key(child: &FolderChild) -> &str {
201→        match child {
202→            FolderChild::Folder(f) => f.ipns_name.as_str(),
203→            FolderChild::File(f) => f.file_meta_ipns_name.as_str(),
204→        }
205→    }
206→
207→    let local_by_ipns: std::collections::HashMap<String, &FolderChild> = local
208→        .children.iter().map(|c| (child_ipns_key(c).to_string(), c)).collect();
209→
210→    let mut merged: Vec<FolderChild> = Vec::new();
211→    let mut seen_ipns: std::collections::HashSet<String> = std::collections::HashSet::new();
212→
213→    for remote_child in &remote.children {
214→        let ipns = child_ipns_key(remote_child).to_string();
215→        if let Some(local_child) = local_by_ipns.get(&ipns) {
216→            merged.push((*local_child).clone());
217→        } else {
218→            merged.push(remote_child.clone());
219→        }
220→        seen_ipns.insert(ipns);
221→    }
222→
223→    for local_child in &local.children {
224→        let ipns = child_ipns_key(local_child).to_string();
225→        if !seen_ipns.contains(&ipns) {
226→            merged.push(local_child.clone());
227→        }
228→    }
229→
230→    cipherbox_core::folder::FolderMetadata { version: "v2".to_string(), children: merged }
231→}
