233→/// Spawn a background OS thread to upload encrypted metadata and publish via IPNS.
234→#[cfg(any(feature = "fuse", feature = "winfsp"))]
235→pub fn spawn_metadata_publish(
236→    api: Arc<ApiClient>,
237→    rt: tokio::runtime::Handle,
238→    metadata: cipherbox_core::folder::FolderMetadata,
239→    folder_key: Vec<u8>,
240→    ipns_private_key: Vec<u8>,
241→    ipns_name: String,
242→    old_metadata_cid: Option<String>,
243→    coordinator: Arc<PublishCoordinator>,
244→) {
245→    std::thread::spawn(move || {
246→        let result = rt.block_on(async {
247→            let lock = coordinator.get_lock(&ipns_name);
248→            let _guard = lock.lock().await;
249→
250→            let json_bytes = encrypt_metadata_to_json(&metadata, &folder_key)?;
251→            let seq = coordinator.resolve_sequence(&api, &ipns_name).await?;
252→            let new_cid = cipherbox_api_client::ipfs::upload_content(&api, &json_bytes)
253→                .await.map_err(|e| format!("{}", e))?;
254→
255→            let ipns_key_arr: [u8; 32] = ipns_private_key.try_into()
256→                .map_err(|_| "Invalid IPNS private key length".to_string())?;
257→            let new_seq = seq + 1;
258→            let value = format!("/ipfs/{}", new_cid);
259→            let record = cipherbox_core::create_ipns_record(&ipns_key_arr, &value, new_seq, 86_400_000)
260→                .map_err(|e| format!("IPNS record creation failed: {}", e))?;
261→            let marshaled = cipherbox_core::marshal_ipns_record(&record)
262→                .map_err(|e| format!("IPNS record marshal failed: {}", e))?;
263→
264→            use base64::Engine;
265→            let record_b64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);
266→
267→            let req = cipherbox_api_client::IpnsPublishRequest {
268→                ipns_name: ipns_name.clone(),
269→                record: record_b64,
270→                metadata_cid: new_cid.clone(),
271→                encrypted_ipns_private_key: None,
272→                key_epoch: None,
273→                expected_sequence_number: Some(seq.to_string()),
274→            };
275→
276→            match cipherbox_api_client::ipns::publish_ipns(&api, &req).await.map_err(|e| format!("{}", e))? {
277→                cipherbox_api_client::PublishResult::Success => {
278→                    coordinator.record_publish(&ipns_name, new_seq);
279→                    if let Some(old) = old_metadata_cid {
280→                        let _ = cipherbox_api_client::ipfs::unpin_content(&api, &old).await;
281→                    }
282→                    log::info!("Background metadata publish succeeded for {}", ipns_name);
283→                }
284→                cipherbox_api_client::PublishResult::Conflict { current_sequence_number } => {
285→                    log::warn!("Conflict for {}: expected seq {}, server has {}", ipns_name, seq, current_sequence_number);
286→
287→                    let fresh_seq = coordinator.resolve_sequence(&api, &ipns_name).await?;
288→                    let remote_resolve = cipherbox_api_client::ipns::resolve_ipns(&api, &ipns_name)
289→                        .await.map_err(|e| format!("{}", e))?;
290→                    let remote_bytes = cipherbox_api_client::ipfs::fetch_content(&api, &remote_resolve.cid)
291→                        .await.map_err(|e| format!("{}", e))?;
292→                    let remote_metadata = cipherbox_core::decrypt_metadata_from_ipfs_public(&remote_bytes, &folder_key)?;
293→
294→                    let merged_metadata = merge_folder_children(&metadata, remote_metadata);
295→
296→                    let jitter_ms = (std::time::SystemTime::now()
297→                        .duration_since(std::time::UNIX_EPOCH).unwrap_or_default()
298→                        .subsec_nanos() % 400) as u64 + 100;
299→                    tokio::time::sleep(std::time::Duration::from_millis(jitter_ms)).await;
300→
301→                    let retry_json = encrypt_metadata_to_json(&merged_metadata, &folder_key)?;
302→                    let retry_cid = cipherbox_api_client::ipfs::upload_content(&api, &retry_json)
303→                        .await.map_err(|e| format!("{}", e))?;
304→
305→                    let retry_seq = fresh_seq + 1;
306→                    let retry_value = format!("/ipfs/{}", retry_cid);
307→                    let retry_record = cipherbox_core::create_ipns_record(&ipns_key_arr, &retry_value, retry_seq, 86_400_000)
308→                        .map_err(|e| format!("IPNS retry record failed: {}", e))?;
309→                    let retry_marshaled = cipherbox_core::marshal_ipns_record(&retry_record)
310→                        .map_err(|e| format!("IPNS retry marshal failed: {}", e))?;
311→                    let retry_b64 = base64::engine::general_purpose::STANDARD.encode(&retry_marshaled);
312→
313→                    let retry_cid_for_cleanup = retry_cid.clone();
314→                    let retry_req = cipherbox_api_client::IpnsPublishRequest {
315→                        ipns_name: ipns_name.clone(),
316→                        record: retry_b64,
317→                        metadata_cid: retry_cid,
318→                        encrypted_ipns_private_key: None,
319→                        key_epoch: None,
320→                        expected_sequence_number: Some(fresh_seq.to_string()),
321→                    };
322→
323→                    match cipherbox_api_client::ipns::publish_ipns(&api, &retry_req).await.map_err(|e| format!("{}", e))? {
324→                        cipherbox_api_client::PublishResult::Success => {
325→                            coordinator.record_publish(&ipns_name, retry_seq);
326→                            let _ = cipherbox_api_client::ipfs::unpin_content(&api, &new_cid).await;
327→                            if let Some(old) = old_metadata_cid {
328→                                let _ = cipherbox_api_client::ipfs::unpin_content(&api, &old).await;
329→                            }
330→                            log::info!("Conflict resolved for {} after retry (seq {})", ipns_name, retry_seq);
331→                        }
332→                        cipherbox_api_client::PublishResult::Conflict { .. } => {
333→                            let _ = cipherbox_api_client::ipfs::unpin_content(&api, &new_cid).await;
334→                            let _ = cipherbox_api_client::ipfs::unpin_content(&api, &retry_cid_for_cleanup).await;
335→                            return Err(format!("Persistent conflict for {}", ipns_name));
336→                        }
337→                    }
338→                }
339→            }
340→            Ok::<(), String>(())
341→        });
342→        if let Err(e) = result {
343→            log::error!("Background metadata publish failed: {}", e);
344→        }
345→    });
346→}
