348→/// Add a BinEntry to the user's encrypted recycle bin IPNS record.
349→#[cfg(any(feature = "fuse", feature = "winfsp"))]
350→pub fn spawn_bin_entry_publish(
351→    api: Arc<ApiClient>,
352→    rt: tokio::runtime::Handle,
353→    entry: cipherbox_core::bin::BinEntry,
354→    user_private_key: Zeroizing<Vec<u8>>,
355→    user_public_key: Vec<u8>,
356→    coordinator: Arc<PublishCoordinator>,
357→) {
358→    std::thread::spawn(move || {
359→        let result = rt.block_on(async {
360→            let pk_arr: [u8; 32] = user_private_key.as_slice().try_into()
361→                .map_err(|_| "Invalid private key length for bin derivation".to_string())?;
362→            let (bin_ipns_private_key, _bin_ipns_public_key, bin_ipns_name) =
363→                cipherbox_crypto::derive_bin_ipns_keypair(&pk_arr)
364→                    .map_err(|e| format!("Bin IPNS derivation failed: {}", e))?;
365→
366→            let lock = coordinator.get_lock(&bin_ipns_name);
367→            let _guard = lock.lock().await;
368→
369→            let (mut bin_metadata, existing_cid) = match cipherbox_api_client::ipns::resolve_ipns(&api, &bin_ipns_name).await {
370→                Ok(resp) => {
371→                    match cipherbox_api_client::ipfs::fetch_content(&api, &resp.cid).await {
372→                        Ok(bytes) => {
373→                            match cipherbox_core::decrypt_bin_metadata(&bytes, &user_private_key) {
374→                                Ok(meta) => (meta, Some(resp.cid)),
375→                                Err(e) => {
376→                                    log::warn!("Failed to decrypt bin metadata: {}", e);
377→                                    return Err(format!("Bin decrypt failed: {}", e));
378→                                }
379→                            }
380→                        }
381→                        Err(e) => {
382→                            log::warn!("Failed to fetch bin metadata blob: {}", e);
383→                            return Err(format!("Bin fetch failed: {}", e));
384→                        }
385→                    }
386→                }
387→                Err(e) => {
388→                    let e_str = format!("{}", e);
389→                    if e_str.to_lowercase().contains("not found") {
390→                        (cipherbox_core::empty_bin_metadata(), None)
391→                    } else {
392→                        log::warn!("Failed to resolve bin IPNS: {}", e);
393→                        return Err(format!("Bin resolve failed: {}", e));
394→                    }
395→                }
396→            };
397→
398→            bin_metadata.sequence_number += 1;
399→            bin_metadata.entries.push(entry);
400→
401→            let encrypted = cipherbox_core::encrypt_bin_metadata(&bin_metadata, &user_public_key)
402→                .map_err(|e| format!("Bin metadata encryption failed: {}", e))?;
403→
404→            let new_cid = cipherbox_api_client::ipfs::upload_content(&api, &encrypted)
405→                .await.map_err(|e| format!("{}", e))?;
406→
407→            let seq = coordinator.resolve_sequence(&api, &bin_ipns_name).await.unwrap_or(0);
408→            let new_seq = seq + 1;
409→
410→            let bin_ipns_key_arr: [u8; 32] = bin_ipns_private_key.as_slice().try_into()
411→                .map_err(|_| "Invalid bin IPNS key length".to_string())?;
412→            let value = format!("/ipfs/{}", new_cid);
413→            let record = cipherbox_core::create_ipns_record(&bin_ipns_key_arr, &value, new_seq, 86_400_000)
414→                .map_err(|e| format!("Bin IPNS record creation failed: {}", e))?;
415→            let marshaled = cipherbox_core::marshal_ipns_record(&record)
416→                .map_err(|e| format!("Bin IPNS marshal failed: {}", e))?;
417→
418→            use base64::Engine;
419→            let record_b64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);
420→
421→            let req = cipherbox_api_client::IpnsPublishRequest {
422→                ipns_name: bin_ipns_name.clone(),
423→                record: record_b64,
424→                metadata_cid: new_cid,
425→                encrypted_ipns_private_key: None,
426→                key_epoch: None,
427→                expected_sequence_number: Some(seq.to_string()),
428→            };
429→
430→            match cipherbox_api_client::ipns::publish_ipns(&api, &req).await.map_err(|e| format!("{}", e))? {
431→                cipherbox_api_client::PublishResult::Success => {
432→                    coordinator.record_publish(&bin_ipns_name, new_seq);
433→                    if let Some(old) = existing_cid {
434→                        let _ = cipherbox_api_client::ipfs::unpin_content(&api, &old).await;
435→                    }
436→                    log::info!("Bin entry published");
437→                }
438→                cipherbox_api_client::PublishResult::Conflict { current_sequence_number } => {
439→                    log::warn!("Bin IPNS publish conflict (expected {}, server {})", seq, current_sequence_number);
440→                }
441→            }
442→
443→            Ok::<(), String>(())
444→        });
445→        if let Err(e) = result {
446→            log::error!("Background bin entry publish failed: {}", e);
447→        }
448→    });
449→}
