459→    pub public_key: Zeroizing<Vec<u8>>,
460→    pub root_folder_key: Zeroizing<Vec<u8>>,
461→    pub root_ipns_name: String,
462→    pub rt: tokio::runtime::Handle,
463→    pub next_fh: AtomicU64,
464→    pub open_files: HashMap<u64, file_handle::OpenFileHandle>,
465→    pub temp_dir: PathBuf,
466→    pub tee_public_key: Option<Vec<u8>>,
467→    pub tee_key_epoch: Option<u32>,
468→    pub refresh_rx: std::sync::mpsc::Receiver<PendingRefresh>,
469→    pub refresh_tx: std::sync::mpsc::Sender<PendingRefresh>,
470→    pub mutated_folders: HashMap<u64, std::time::Instant>,
471→    pub prefetching: std::collections::HashSet<String>,
472→    pub content_rx: std::sync::mpsc::Receiver<PendingContent>,
473→    pub content_tx: std::sync::mpsc::Sender<PendingContent>,
474→    pub pending_content: HashMap<u64, Vec<u8>>,
475→    pub upload_rx: std::sync::mpsc::Receiver<UploadComplete>,
