481→#[cfg(any(feature = "fuse", feature = "winfsp"))]
482→impl CipherBoxFS {
483→    pub fn get_folder_key(&self, folder_ino: u64) -> Option<Vec<u8>> {
484→        self.inodes.get(folder_ino).and_then(|inode| match &inode.kind {
485→            inode::InodeKind::Root { .. } => Some(self.root_folder_key.to_vec()),
486→            inode::InodeKind::Folder { folder_key, .. } => Some(folder_key.to_vec()),
487→            _ => None,
488→        })
489→    }
490→
491→    pub fn build_folder_metadata(&self, folder_ino: u64) -> Result<(cipherbox_core::FolderMetadata, Vec<u8>, Vec<u8>, String, Option<String>), String> {
492→        let (folder_key, ipns_private_key, ipns_name, child_inos) = {
493→            let inode = self.inodes.get(folder_ino).ok_or_else(|| format!("Folder inode {} not found", folder_ino))?;
494→            let children = inode.children.clone().unwrap_or_default();
495→            match &inode.kind {
496→                inode::InodeKind::Root { ipns_private_key, ipns_name } => {
497→                    let key = ipns_private_key.as_ref().ok_or("Root IPNS key not available")?.to_vec();
498→                    let name = ipns_name.as_ref().ok_or("Root IPNS name not available")?.clone();
499→                    (self.root_folder_key.to_vec(), key, name, children)
500→                }
501→                inode::InodeKind::Folder { folder_key, ipns_private_key, ipns_name, .. } => {
502→                    let key = ipns_private_key.as_ref().ok_or("Subfolder IPNS key not available")?.to_vec();
503→                    (folder_key.to_vec(), key, ipns_name.clone(), children)
504→                }
505→                _ => return Err("Cannot update metadata for non-folder inode".to_string()),
506→            }
507→        };
508→
509→        let mut metadata_children = Vec::new();
510→        for &child_ino in &child_inos {
511→            let child = self.inodes.get(child_ino).ok_or_else(|| format!("Child inode {} not found", child_ino))?;
512→            match &child.kind {
513→                inode::InodeKind::Folder { ipns_name: child_ipns, encrypted_folder_key, ipns_private_key: child_ipns_key, .. } => {
514→                    let ipns_key_encrypted = if let Some(key) = child_ipns_key {
515→                        hex::encode(cipherbox_crypto::wrap_key(key, &self.public_key).map_err(|e| format!("Wrap IPNS key: {}", e))?)
516→                    } else { String::new() };
517→                    let now_ms = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_millis() as u64;
518→                    let created_ms = child.attr.crtime.duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_millis() as u64;
519→                    let modified_ms = child.attr.mtime.duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_millis() as u64;
520→                    metadata_children.push(cipherbox_core::FolderChild::Folder(cipherbox_core::FolderEntry {
521→                        id: uuid_from_ino(child_ino), name: child.name.clone(), ipns_name: child_ipns.clone(),
522→                        folder_key_encrypted: encrypted_folder_key.clone(), ipns_private_key_encrypted: ipns_key_encrypted,
523→                        created_at: if created_ms > 0 { created_ms } else { now_ms },
524→                        modified_at: if modified_ms > 0 { modified_ms } else { now_ms },
525→                    }));
526→                }
527→                inode::InodeKind::File { file_meta_ipns_name, file_ipns_private_key, file_ipns_key_encrypted_hex, .. } => {
528→                    let now_ms = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_millis() as u64;
529→                    let created_ms = child.attr.crtime.duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_millis() as u64;
530→                    let modified_ms = child.attr.mtime.duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_millis() as u64;
531→                    let ipns_name_val = match file_meta_ipns_name {
532→                        Some(name) if !name.is_empty() => name.clone(),
533→                        _ => { log::error!("File '{}' (ino {}) has no fileMetaIpnsName", child.name, child_ino); continue; }
534→                    };
535→                    let ipns_key_encrypted = if let Some(h) = file_ipns_key_encrypted_hex { Some(h.clone()) }
536→                        else if let Some(key) = file_ipns_private_key {
537→                            cipherbox_crypto::wrap_key(key, &self.public_key).ok().map(|w| hex::encode(&w))
538→                        } else { None };
539→                    metadata_children.push(cipherbox_core::FolderChild::File(cipherbox_core::FilePointer {
540→                        id: uuid_from_ino(child_ino), name: child.name.clone(), file_meta_ipns_name: ipns_name_val,
541→                        ipns_private_key_encrypted: ipns_key_encrypted,
542→                        created_at: if created_ms > 0 { created_ms } else { now_ms },
543→                        modified_at: if modified_ms > 0 { modified_ms } else { now_ms },
544→                    }));
545→                }
546→                _ => {}
547→            }
548→        }
549→
550→        let metadata = cipherbox_core::FolderMetadata { version: "v2".to_string(), children: metadata_children };
551→        let old_cid = self.metadata_cache.get(&ipns_name).map(|c| c.cid.clone());
552→        Ok((metadata, folder_key, ipns_private_key, ipns_name, old_cid))
553→    }
554→
555→    pub fn update_folder_metadata(&mut self, folder_ino: u64) -> Result<(), String> {
556→        self.mutated_folders.insert(folder_ino, std::time::Instant::now());
557→        let (metadata, folder_key, ipns_private_key, ipns_name, old_cid) = self.build_folder_metadata(folder_ino)?;
558→        spawn_metadata_publish(self.api.clone(), self.rt.clone(), metadata, folder_key, ipns_private_key, ipns_name, old_cid, self.publish_coordinator.clone());
559→        Ok(())
560→    }
561→
562→    pub fn drain_upload_completions(&mut self) {
563→        while let Ok(result) = self.upload_rx.try_recv() {
564→            if let Some(inode) = self.inodes.get_mut(result.ino) {
565→                if inode.write_generation == result.write_generation {
566→                    if let inode::InodeKind::File { ref mut cid, .. } = inode.kind { *cid = result.new_cid.clone(); }
567→                }
568→            }
569→            if let Some(inode) = self.inodes.get(result.ino) {
570→                if inode.write_generation == result.write_generation {
571→                    if let Some(plaintext) = self.pending_content.remove(&result.ino) { self.content_cache.set(&result.new_cid, plaintext); }
572→                }
573→            }
574→            for pruned_cid in &result.pruned_cids {
575→                let api = self.api.clone(); let cid = pruned_cid.clone();
576→                self.rt.spawn(async move { let _ = cipherbox_api_client::ipfs::unpin_content(&api, &cid).await; });
577→            }
578→            if let Some(entry) = self.publish_queue.get_mut(&result.parent_ino) { entry.pending_uploads = entry.pending_uploads.saturating_sub(1); }
579→        }
580→        self.flush_publish_queue();
581→    }
582→
583→    pub fn queue_publish(&mut self, folder_ino: u64, has_pending_upload: bool) {
584→        let entry = self.publish_queue.entry(folder_ino).or_insert(PublishQueueEntry { first_dirty: std::time::Instant::now(), pending_uploads: 0 });
585→        if has_pending_upload { entry.pending_uploads += 1; }
586→        self.mutated_folders.insert(folder_ino, std::time::Instant::now());
587→    }
588→
589→    fn flush_publish_queue(&mut self) {
590→        let now = std::time::Instant::now();
591→        let debounce = std::time::Duration::from_millis(1500);
592→        let safety_valve = std::time::Duration::from_secs(10);
593→        let ready: Vec<u64> = self.publish_queue.iter()
594→            .filter(|(_, e)| { let elapsed = now.duration_since(e.first_dirty); elapsed >= safety_valve || (e.pending_uploads == 0 && elapsed >= debounce) })
595→            .map(|(&ino, _)| ino).collect();
596→        for folder_ino in ready {
597→            self.publish_queue.remove(&folder_ino);
598→            match self.build_folder_metadata(folder_ino) {
599→                Ok((m, fk, ipk, in_, oc)) => spawn_metadata_publish(self.api.clone(), self.rt.clone(), m, fk, ipk, in_, oc, self.publish_coordinator.clone()),
600→                Err(e) => log::error!("Failed to build folder metadata for publish (ino {}): {}", folder_ino, e),
601→            }
602→        }
603→    }
604→
605→    pub fn drain_refresh_completions(&mut self) {
606→        let cutoff = std::time::Instant::now() - std::time::Duration::from_secs(30);
607→        self.mutated_folders.retain(|_, ts| *ts > cutoff);
608→        while let Ok(refresh) = self.refresh_rx.try_recv() {
609→            if self.mutated_folders.contains_key(&refresh.ino) || self.publish_queue.contains_key(&refresh.ino) {
610→                self.metadata_cache.set(&refresh.ipns_name, refresh.metadata.clone(), refresh.cid);
611→                continue;
612→            }
613→            self.metadata_cache.set(&refresh.ipns_name, refresh.metadata.clone(), refresh.cid.clone());
614→            if let Err(e) = self.inodes.populate_folder(refresh.ino, &refresh.metadata, &self.private_key, &self.public_key, true) {
615→                log::warn!("Drain refresh apply failed for ino {}: {}", refresh.ino, e);
616→            }
617→            let unresolved = self.inodes.get_unresolved_file_pointers();
618→            if !unresolved.is_empty() {
619→                let folder_key = self.inodes.get(refresh.ino).and_then(|i| match &i.kind {
620→                    inode::InodeKind::Root { .. } => Some(self.root_folder_key.to_vec()),
621→                    inode::InodeKind::Folder { folder_key, .. } => Some(folder_key.to_vec()),
622→                    _ => None,
623→                });
624→                if let Some(fk) = folder_key {
625→                    for (ino, fp_ipns) in &unresolved {
626→                        if let Ok(fk_arr) = <[u8; 32]>::try_from(fk.as_slice()) {
627→                            let api = self.api.clone();
628→                            let resolve_result = block_with_timeout(&self.rt, async {
629→                                let resp = cipherbox_api_client::ipns::resolve_ipns(&api, fp_ipns).await.map_err(|e| format!("{}", e))?;
630→                                cipherbox_api_client::ipfs::fetch_content(&api, &resp.cid).await.map_err(|e| format!("{}", e))
631→                            });
632→                            match resolve_result {
633→                                Ok(enc_bytes) => {
634→                                    match cipherbox_core::decrypt_file_metadata_from_ipfs_public(&enc_bytes, &fk_arr) {
635→                                        Ok(fm) => self.inodes.resolve_file_pointer(*ino, fm.cid, fm.file_key_encrypted, fm.file_iv, fm.size, fm.encryption_mode, fm.versions),
636→                                        Err(e) => log::warn!("FilePointer decrypt failed for ino {}: {}", ino, e),
637→                                    }
638→                                }
639→                                Err(e) => log::warn!("FilePointer resolve failed for ino {}: {}", ino, e),
640→                            }
641→                        }
642→                    }
643→                }
644→            }
645→        }
646→    }
647→
648→    pub fn drain_content_prefetches(&mut self) {
649→        while let Ok(msg) = self.content_rx.try_recv() {
650→            match msg {
651→                PendingContent::Success { cid, data } => { self.prefetching.remove(&cid); self.content_cache.set(&cid, data); }
652→                PendingContent::Failure { cid } => { self.prefetching.remove(&cid); }
653→            }
654→        }
655→    }
656→}
