659→fn uuid_from_ino(ino: u64) -> String {
660→    format!("{:08x}-{:04x}-4{:03x}-{:04x}-{:012x}", (ino >> 32) as u32, ((ino >> 16) & 0xFFFF) as u16,
661→        (ino & 0xFFF) as u16, (0x8000 | (ino & 0x3FFF)) as u16, ino & 0xFFFFFFFFFFFF)
662→}
