  1→//! WinFsp FileSystemContext implementation for CipherBoxFS.
  2→//!
  3→//! Delegates to category-specific modules:
  4→//! - `read_ops`: get_volume_info, get_security_by_name, open, close, read, get_file_info, get_security, flush
  5→//! - `write_ops`: create, write, overwrite, cleanup, set_basic_info, set_file_size, set_delete, rename
  6→//! - `dir_ops`: read_directory
  7→//!
  8→//! Uses `Arc<Mutex<CipherBoxFS>>` for interior mutability (WinFsp callbacks
  9→//! receive `&self`, not `&mut self`, because the driver invokes callbacks on
 10→//! any thread).
 11→//!
 12→//! Path resolution: WinFsp is path-based (receives `\folder\file.txt`), while
 13→//! the inode table uses parent_ino + name lookups. `resolve_path()` bridges
 14→//! this by walking the inode table component-by-component from the root.
 15→
 16→#[cfg(feature = "winfsp")]
 17→pub(crate) mod implementation {
 18→    use std::ffi::c_void;
 19→    use std::sync::{Arc, Mutex};
 20→    use std::time::{Duration, SystemTime, UNIX_EPOCH};
 21→
 22→    use winfsp::filesystem::{
 23→        DirMarker, FileInfo, FileSystemContext, FileSecurity, OpenFileInfo,
 24→    };
 25→    use widestring::U16CStr;
