 34→    // ── NTSTATUS error helpers ─────────────────────────────────────────
 35→    // FspError::IO cannot be used in const context since ErrorKind may not be
 36→    // const-constructible, so we use inline functions.
 37→    pub fn status_object_name_not_found() -> FspError { FspError::NTSTATUS(0xC0000034_u32 as i32) }
 38→    pub fn status_invalid_parameter() -> FspError { FspError::NTSTATUS(0xC000000D_u32 as i32) }
 39→    pub fn status_object_name_collision() -> FspError { FspError::NTSTATUS(0xC0000035_u32 as i32) }
 40→    pub fn status_directory_not_empty() -> FspError { FspError::NTSTATUS(0xC0000101_u32 as i32) }
 41→    pub fn status_invalid_handle() -> FspError { FspError::NTSTATUS(0xC0000008_u32 as i32) }
 42→    pub fn status_io_device_error() -> FspError { FspError::IO(std::io::ErrorKind::Other) }
