 44→    /// Permissive self-relative security descriptor granting FILE_ALL_ACCESS
 45→    /// to Everyone (S-1-1-0). CipherBox is single-user; encryption is the real
 46→    /// access control, so we grant full NTFS permissions.
 47→    ///
 48→    /// Layout: 20-byte header, 28-byte DACL (one ACE), 12-byte Owner, 12-byte Group.
 49→    ///
 50→    /// Without a valid descriptor, WinFsp's `FspFileSystemOpenCheck()` strips
 51→    /// DELETE access from `GrantedAccess` when `SecurityDescriptorSize == 0`,
 52→    /// which prevents directory deletion via `Remove-Item` / `RemoveDirectory()`.
 53→    pub static PERMISSIVE_SD: [u8; 72] = [
 54→        // ── SECURITY_DESCRIPTOR header (20 bytes) ──
 55→        0x01,                   // Revision
 56→        0x00,                   // Sbz1
 57→        0x04, 0x80,             // Control: SE_SELF_RELATIVE | SE_DACL_PRESENT
 58→        0x30, 0x00, 0x00, 0x00, // OwnerOffset = 48
 59→        0x3C, 0x00, 0x00, 0x00, // GroupOffset = 60
 60→        0x00, 0x00, 0x00, 0x00, // SaclOffset = 0 (none)
 61→        0x14, 0x00, 0x00, 0x00, // DaclOffset = 20
 62→        // ── ACL header (8 bytes) ──
 63→        0x02,                   // AclRevision
 64→        0x00,                   // Sbz1
 65→        0x1C, 0x00,             // AclSize = 28
 66→        0x01, 0x00,             // AceCount = 1
 67→        0x00, 0x00,             // Sbz2
 68→        // ── ACCESS_ALLOWED_ACE (20 bytes) ──
 69→        0x00,                   // AceType = ACCESS_ALLOWED
 70→        0x00,                   // AceFlags
 71→        0x14, 0x00,             // AceSize = 20
 72→        0xFF, 0x01, 0x1F, 0x00, // Mask = FILE_ALL_ACCESS (0x001F01FF)
 73→        // SID: S-1-1-0 (Everyone)
 74→        0x01, 0x01,             // Revision, SubAuthorityCount
 75→        0x00, 0x00, 0x00, 0x00, 0x00, 0x01, // IdentifierAuthority
 76→        0x00, 0x00, 0x00, 0x00, // SubAuthority[0]
 77→        // ── Owner SID: S-1-1-0 (12 bytes) ──
 78→        0x01, 0x01,
 79→        0x00, 0x00, 0x00, 0x00, 0x00, 0x01,
 80→        0x00, 0x00, 0x00, 0x00,
 81→        // ── Group SID: S-1-1-0 (12 bytes) ──
 82→        0x01, 0x01,
 83→        0x00, 0x00, 0x00, 0x00, 0x00, 0x01,
 84→        0x00, 0x00, 0x00, 0x00,
 85→    ];
