 89→    /// WinFsp filesystem context wrapping the shared CipherBoxFS.
 90→    ///
 91→    /// All callbacks receive `&self`, so we use `Arc<Mutex<CipherBoxFS>>` for
 92→    /// interior mutability. The tokio runtime handle is used for blocking on
 93→    /// async operations from WinFsp's synchronous callback threads.
 94→    pub struct WinFspContext {
 95→        pub inner: Arc<Mutex<CipherBoxFS>>,
 96→        pub rt: tokio::runtime::Handle,
 97→    }
