172→    /// Populate a WinFsp FileInfo from our platform-agnostic FileAttrs.
173→    pub fn fill_file_info(attrs: &FileAttrs) -> FileInfo {
174→        let mut info = FileInfo::default();
175→        info.file_attributes = if attrs.is_dir {
176→            0x10 // FILE_ATTRIBUTE_DIRECTORY
177→        } else {
178→            0x80 // FILE_ATTRIBUTE_NORMAL
179→        };
180→        info.file_size = attrs.size;
181→        info.allocation_size = (attrs.size + 4095) & !4095; // round up to 4K
182→        info.creation_time = systemtime_to_filetime(attrs.crtime);
183→        info.last_access_time = systemtime_to_filetime(attrs.atime);
184→        info.last_write_time = systemtime_to_filetime(attrs.mtime);
185→        info.change_time = systemtime_to_filetime(attrs.ctime);
186→        info
187→    }
