251→    /// Async version of content download + decrypt for background prefetch tasks.
252→    pub async fn fetch_and_decrypt_content_async(
253→        api: &cipherbox_api_client::ApiClient,
254→        cid: &str,
255→        encrypted_file_key_hex: &str,
256→        iv_hex: &str,
257→        encryption_mode: &str,
258→        private_key: &[u8],
259→    ) -> Result<Vec<u8>, String> {
260→        let encrypted_bytes = cipherbox_api_client::ipfs::fetch_content(api, cid).await.map_err(|e| e.to_string())?;
261→        let encrypted_file_key = hex::decode(encrypted_file_key_hex)
262→            .map_err(|_| "Invalid file key hex".to_string())?;
263→        let file_key = zeroize::Zeroizing::new(
264→            cipherbox_crypto::ecies::unwrap_key(&encrypted_file_key, private_key)
265→                .map_err(|e| format!("File key unwrap failed: {}", e))?,
266→        );
267→        let file_key_arr: [u8; 32] = file_key
268→            .as_slice()
269→            .try_into()
270→            .map_err(|_| "Invalid file key length".to_string())?;
271→
272→        let plaintext = if encryption_mode == "CTR" {
273→            let iv =
274→                hex::decode(iv_hex).map_err(|_| "Invalid file IV hex".to_string())?;
275→            let iv_arr: [u8; 16] = iv
276→                .try_into()
277→                .map_err(|_| "Invalid CTR IV length (expected 16)".to_string())?;
278→            cipherbox_crypto::aes_ctr::decrypt_aes_ctr(
279→                &encrypted_bytes,
280→                &file_key_arr,
281→                &iv_arr,
282→            )
283→            .map_err(|e| format!("CTR decryption failed: {}", e))?
284→        } else {
285→            let iv =
286→                hex::decode(iv_hex).map_err(|_| "Invalid file IV hex".to_string())?;
287→            let iv_arr: [u8; 12] = iv
288→                .try_into()
289→                .map_err(|_| "Invalid GCM IV length (expected 12)".to_string())?;
290→            cipherbox_crypto::aes::decrypt_aes_gcm(
291→                &encrypted_bytes,
292→                &file_key_arr,
293→                &iv_arr,
294→            )
295→            .map_err(|e| format!("GCM decryption failed: {}", e))?
296→        };
297→
298→        Ok(plaintext)
299→    }
