301→    /// Encrypt and publish per-file FileMetadata to the file's own IPNS record.
302→    pub async fn publish_file_metadata(
303→        api: &cipherbox_api_client::ApiClient,
304→        file_meta: &cipherbox_core::folder::FileMetadata,
305→        folder_key: &[u8],
306→        file_ipns_private_key: &zeroize::Zeroizing<Vec<u8>>,
307→        file_ipns_name: &str,
308→        coordinator: &crate::fuse::PublishCoordinator,
309→    ) -> Result<(), String> {
310→        let folder_key_arr: [u8; 32] = folder_key.try_into().map_err(|_| {
311→            "Invalid folder key length for FileMetadata encryption".to_string()
312→        })?;
313→
314→        // Encrypt FileMetadata with parent folder key
315→        let sealed =
316→            cipherbox_core::folder::encrypt_file_metadata(file_meta, &folder_key_arr)
317→                .map_err(|e| format!("FileMetadata encryption failed: {}", e))?;
318→
319→        // Package as JSON envelope: { "iv": hex, "data": base64 }
320→        let iv_hex = hex::encode(&sealed[..12]);
321→        use base64::Engine;
322→        let data_base64 =
323→            base64::engine::general_purpose::STANDARD.encode(&sealed[12..]);
324→        let json = serde_json::json!({ "iv": iv_hex, "data": data_base64 });
325→        let json_bytes = serde_json::to_vec(&json)
326→            .map_err(|e| format!("FileMetadata JSON serialization failed: {}", e))?;
327→
328→        // Upload encrypted file metadata to IPFS
329→        let file_meta_cid =
330→            cipherbox_api_client::ipfs::upload_content(api, &json_bytes).await.map_err(|e| e.to_string())?;
331→
332→        // Resolve current IPNS sequence number
333→        let seq = coordinator
334→            .resolve_sequence(api, file_ipns_name)
335→            .await?;
336→
337→        // Create and sign IPNS record
338→        let ipns_key_arr: [u8; 32] = file_ipns_private_key
339→            .as_slice()
340→            .try_into()
341→            .map_err(|_| "Invalid file IPNS private key length".to_string())?;
342→        let new_seq = seq + 1;
343→        let value = format!("/ipfs/{}", file_meta_cid);
344→        let record = cipherbox_core::ipns::create_ipns_record(
345→            &ipns_key_arr,
346→            &value,
347→            new_seq,
348→            86_400_000,
349→        )
350→        .map_err(|e| format!("File IPNS record creation failed: {}", e))?;
351→        let marshaled = cipherbox_core::ipns::marshal_ipns_record(&record)
352→            .map_err(|e| format!("File IPNS record marshal failed: {}", e))?;
353→
354→        let record_b64 =
355→            base64::engine::general_purpose::STANDARD.encode(&marshaled);
356→
357→        // Per-file IPNS publishes do not use conflict detection -- file metadata
358→        // is owned by the file's own IPNS keypair and conflicts are inherently
359→        // avoided by the per-file sequence number management.
360→        let req = cipherbox_api_client::IpnsPublishRequest {
361→            ipns_name: file_ipns_name.to_string(),
362→            record: record_b64,
363→            metadata_cid: file_meta_cid.clone(),
364→            encrypted_ipns_private_key: None,
365→            key_epoch: None,
366→            expected_sequence_number: None,
367→        };
368→        match cipherbox_api_client::ipns::publish_ipns(api, &req).await.map_err(|e| e.to_string())? {
369→            cipherbox_api_client::PublishResult::Success => {}
370→            cipherbox_api_client::PublishResult::Conflict { .. } => {
371→                log::warn!("Unexpected conflict on per-file IPNS publish for {}", file_ipns_name);
372→            }
373→        }
374→
375→        coordinator.record_publish(file_ipns_name, new_seq);
376→        log::info!("Per-file IPNS publish succeeded for {}", file_ipns_name);
377→
378→        Ok(())
379→    }
