  1→//! Read operations for Windows WinFsp filesystem.
  2→//!
  3→//! Contains handler logic for: get_volume_info, get_security_by_name, open,
  4→//! close, read, get_file_info, get_security, flush.
  5→
  6→#[cfg(feature = "winfsp")]
  7→pub(crate) mod implementation {
  8→    use std::ffi::c_void;
  9→    use std::sync::atomic::Ordering;
 10→    use std::time::Duration;
 11→
 12→    use winfsp::filesystem::{FileInfo, FileSecurity, OpenFileInfo};
 13→    use widestring::U16CStr;
 14→    use winfsp::FspError;
 15→
 16→    use crate::fuse::constants::CONTENT_DOWNLOAD_TIMEOUT;
 17→    use crate::fuse::file_handle::OpenFileHandle;
 18→    use crate::fuse::inode::InodeKind;
 19→    use crate::fuse::windows::operations::implementation::{
 20→        WinFspContext, WinFspFileContext,
 21→        status_object_name_not_found, status_invalid_parameter,
 22→        status_invalid_handle, status_io_device_error,
 23→        resolve_path, fill_file_info, PERMISSIVE_SD,
 24→        fetch_and_decrypt_file_content, fetch_and_decrypt_content_async,
 25→        is_windows_special,
 26→    };
 27→    use crate::fuse::constants::QUOTA_BYTES;
 28→
 29→    /// get_volume_info handler
 30→    pub fn handle_get_volume_info(
 31→        ctx: &WinFspContext,
 32→        volume_info: &mut winfsp::filesystem::VolumeInfo,
 33→    ) -> Result<(), FspError> {
 34→        let fs = ctx.inner.lock().unwrap();
 35→        let used_bytes: u64 = fs
 36→            .inodes
 37→            .inodes
 38→            .values()
 39→            .filter_map(|inode| match &inode.kind {
 40→                InodeKind::File { size, .. } => Some(*size),
 41→                _ => None,
 42→            })
 43→            .sum();
 44→
 45→        volume_info.total_size = QUOTA_BYTES;
 46→        volume_info.free_size = QUOTA_BYTES.saturating_sub(used_bytes);
 47→        Ok(())
 48→    }
 49→
 50→    /// get_security_by_name handler
 51→    pub fn handle_get_security_by_name(
 52→        ctx: &WinFspContext,
 53→        file_name: &U16CStr,
 54→        security_descriptor: Option<&mut [c_void]>,
 55→    ) -> Result<FileSecurity, FspError> {
 56→        let path = file_name.to_string_lossy();
 57→        let fs = ctx.inner.lock().unwrap();
 58→
 59→        let name_only = path.rsplit('\\').next().unwrap_or(&path);
 60→        if is_windows_special(name_only) {
 61→            return Err(status_object_name_not_found());
 62→        }
 63→
 64→        let (ino, _parent_ino) = resolve_path(&fs, &path)
 65→            .ok_or(status_object_name_not_found())?;
 66→
 67→        let inode = fs
 68→            .inodes
 69→            .get(ino)
 70→            .ok_or(status_object_name_not_found())?;
 71→
 72→        let info = fill_file_info(&inode.attr);
 73→
 74→        if let Some(buf) = security_descriptor {
 75→            if buf.len() >= PERMISSIVE_SD.len() {
 76→                unsafe {
 77→                    std::ptr::copy_nonoverlapping(
 78→                        PERMISSIVE_SD.as_ptr(),
 79→                        buf.as_mut_ptr() as *mut u8,
 80→                        PERMISSIVE_SD.len(),
 81→                    );
 82→                }
 83→            }
 84→        }
 85→
 86→        Ok(FileSecurity {
 87→            attributes: info.file_attributes,
 88→            reparse: false,
 89→            sz_security_descriptor: PERMISSIVE_SD.len() as u64,
 90→        })
 91→    }
 92→
 93→    /// open handler
 94→    pub fn handle_open(
 95→        ctx: &WinFspContext,
 96→        file_name: &U16CStr,
 97→        create_options: u32,
 98→        granted_access: u32,
 99→        file_info: &mut OpenFileInfo,
100→    ) -> Result<WinFspFileContext, FspError> {
101→        let path = file_name.to_string_lossy();
102→        log::info!(
103→            "open() path={} create_options=0x{:08X} granted_access=0x{:08X}",
104→            path, create_options, granted_access
105→        );
106→        let mut fs = ctx.inner.lock().unwrap();
107→
108→        fs.drain_upload_completions();
109→        fs.drain_content_prefetches();
110→
111→        let (ino, _parent_ino) = resolve_path(&fs, &path)
112→            .ok_or(status_object_name_not_found())?;
113→
114→        let inode = fs
115→            .inodes
116→            .get(ino)
117→            .ok_or(status_object_name_not_found())?;
118→        let is_dir = inode.attr.is_dir;
119→
120→        *file_info.as_mut() = fill_file_info(&inode.attr);
121→
122→        if is_dir {
123→            let fh = fs.next_fh.fetch_add(1, Ordering::SeqCst);
124→            return Ok(WinFspFileContext { fh, ino, is_dir: true });
125→        }
126→
127→        let is_write = (granted_access & 0x0006) != 0;
128→
129→        if is_write {
130→            let (cid, encrypted_file_key, iv, encryption_mode) =
131→                match &inode.kind {
132→                    InodeKind::File { cid, encrypted_file_key, iv, encryption_mode, .. } => (
133→                        cid.clone(), encrypted_file_key.clone(), iv.clone(), encryption_mode.clone(),
134→                    ),
135→                    _ => return Err(status_invalid_parameter()),
136→                };
137→
138→            let existing_content = if !cid.is_empty() {
139→                if let Some(cached) = fs.content_cache.get(&cid) {
140→                    Some(cached.to_vec())
141→                } else {
142→                    match fetch_and_decrypt_file_content(&fs, &cid, &encrypted_file_key, &iv, &encryption_mode) {
143→                        Ok(content) => Some(content),
144→                        Err(e) => {
145→                            log::error!("Failed to fetch content for write-open: {}", e);
146→                            return Err(status_io_device_error());
147→                        }
148→                    }
149→                }
150→            } else {
151→                None
152→            };
153→
154→            let fh = fs.next_fh.fetch_add(1, Ordering::SeqCst);
155→            match OpenFileHandle::new_write(ino, &fs.temp_dir, existing_content.as_deref()) {
156→                Ok(handle) => {
157→                    fs.open_files.insert(fh, handle);
158→                    Ok(WinFspFileContext { fh, ino, is_dir: false })
159→                }
160→                Err(e) => {
161→                    log::error!("Failed to create write handle: {}", e);
162→                    Err(status_io_device_error())
163→                }
164→            }
165→        } else {
166→            let (cid, encrypted_file_key, iv, encryption_mode) =
167→                match &inode.kind {
168→                    InodeKind::File { cid, encrypted_file_key, iv, encryption_mode, .. } => (
169→                        cid.clone(), encrypted_file_key.clone(), iv.clone(), encryption_mode.clone(),
170→                    ),
171→                    _ => return Err(status_invalid_parameter()),
172→                };
173→
174→            if !cid.is_empty()
175→                && fs.content_cache.get(&cid).is_none()
176→                && !fs.prefetching.contains(&cid)
177→            {
178→                let api = fs.api.clone();
179→                let rt = fs.rt.clone();
180→                let tx = fs.content_tx.clone();
181→                let cid_clone = cid.clone();
182→                let efk = encrypted_file_key.clone();
183→                let iv_clone = iv.clone();
184→                let enc_mode = encryption_mode.clone();
185→                let pk = fs.private_key.clone();
186→                fs.prefetching.insert(cid.clone());
187→
188→                rt.spawn(async move {
189→                    let result = tokio::time::timeout(
190→                        CONTENT_DOWNLOAD_TIMEOUT,
191→                        fetch_and_decrypt_content_async(
192→                            &api, &cid_clone, &efk, &iv_clone, &enc_mode, &pk,
193→                        ),
194→                    )
195→                    .await;
196→
197→                    match result {
198→                        Ok(Ok(plaintext)) => {
199→                            let _ = tx.send(crate::fuse::PendingContent::Success {
200→                                cid: cid_clone,
201→                                data: plaintext,
202→                            });
203→                        }
204→                        Ok(Err(e)) => {
205→                            log::error!("Prefetch failed for CID {}: {}", cid_clone, e);
206→                            let _ = tx.send(crate::fuse::PendingContent::Failure { cid: cid_clone });
207→                        }
208→                        Err(_) => {
209→                            log::error!("Prefetch timed out for CID {}", cid_clone);
210→                            let _ = tx.send(crate::fuse::PendingContent::Failure { cid: cid_clone });
211→                        }
212→                    }
213→                });
214→            }
215→
216→            let fh = fs.next_fh.fetch_add(1, Ordering::SeqCst);
217→            fs.open_files.insert(fh, OpenFileHandle::new_read(ino));
218→            Ok(WinFspFileContext { fh, ino, is_dir: false })
219→        }
220→    }
