222→    /// close handler
223→    pub fn handle_close(ctx: &WinFspContext, context: WinFspFileContext) {
224→        log::info!("close() ino={} fh={}", context.ino, context.fh);
225→        let mut fs = ctx.inner.lock().unwrap();
226→        fs.drain_upload_completions();
227→
228→        if let Some(handle) = fs.open_files.remove(&context.fh) {
229→            handle.cleanup();
230→        }
231→    }
