233→    /// read handler
234→    pub fn handle_read(
235→        ctx: &WinFspContext,
236→        context: &WinFspFileContext,
237→        buffer: &mut [u8],
238→        offset: u64,
239→    ) -> Result<u32, FspError> {
240→        let mut fs = ctx.inner.lock().unwrap();
241→        fs.drain_upload_completions();
242→        fs.drain_content_prefetches();
243→
244→        let fh = context.fh;
245→        let ino = context.ino;
246→
247→        let has_temp = fs
248→            .open_files
249→            .get(&fh)
250→            .map(|h| h.temp_path.is_some())
251→            .unwrap_or(false);
252→
253→        if has_temp {
254→            match fs.open_files.get(&fh) {
255→                Some(handle) => {
256→                    match handle.read_at(offset as i64, buffer.len() as u32) {
257→                        Ok(data) => {
258→                            let len = std::cmp::min(data.len(), buffer.len());
259→                            buffer[..len].copy_from_slice(&data[..len]);
260→                            return Ok(len as u32);
261→                        }
262→                        Err(e) => {
263→                            log::error!("Temp file read failed: {}", e);
264→                            return Err(status_io_device_error());
265→                        }
266→                    }
267→                }
268→                None => return Err(status_invalid_handle()),
269→            }
270→        }
271→
272→        let (cid, encrypted_file_key_hex, iv_hex, encryption_mode) = {
273→            match fs.inodes.get(ino) {
274→                Some(inode) => match &inode.kind {
275→                    InodeKind::File { cid, encrypted_file_key, iv, encryption_mode, .. } => (
276→                        cid.clone(), encrypted_file_key.clone(), iv.clone(), encryption_mode.clone(),
277→                    ),
278→                    _ => return Err(status_invalid_parameter()),
279→                },
280→                None => return Err(status_object_name_not_found()),
281→            }
282→        };
283→
284→        if cid.is_empty() {
285→            if let Some(content) = fs.pending_content.get(&ino) {
286→                let start = offset as usize;
287→                if start >= content.len() {
288→                    return Ok(0);
289→                }
290→                let end = std::cmp::min(start + buffer.len(), content.len());
291→                let len = end - start;
292→                buffer[..len].copy_from_slice(&content[start..end]);
293→                return Ok(len as u32);
294→            }
295→            return Ok(0);
296→        }
297→
298→        if let Some(handle) = fs.open_files.get(&fh) {
299→            if let Some(ref content) = handle.cached_content {
300→                let start = offset as usize;
301→                if start >= content.len() {
302→                    return Ok(0);
303→                }
304→                let end = std::cmp::min(start + buffer.len(), content.len());
305→                let len = end - start;
306→                buffer[..len].copy_from_slice(&content[start..end]);
307→                return Ok(len as u32);
308→            }
309→        }
310→
311→        let cached_owned = fs.content_cache.get(&cid).map(|c| c.to_vec());
312→        if let Some(cached_owned) = cached_owned {
313→            let start = offset as usize;
314→            if start >= cached_owned.len() {
315→                return Ok(0);
316→            }
317→            let end = std::cmp::min(start + buffer.len(), cached_owned.len());
318→            let len = end - start;
319→            buffer[..len].copy_from_slice(&cached_owned[start..end]);
320→
321→            if let Some(handle) = fs.open_files.get_mut(&fh) {
322→                handle.cached_content = Some(cached_owned);
323→            }
324→            return Ok(len as u32);
325→        }
326→
327→        // Content not cached: start prefetch and poll
328→        if !fs.prefetching.contains(&cid) {
329→            let api = fs.api.clone();
330→            let rt = fs.rt.clone();
331→            let tx = fs.content_tx.clone();
332→            let cid_clone = cid.clone();
333→            let efk = encrypted_file_key_hex.clone();
334→            let iv_clone = iv_hex.clone();
335→            let enc_mode = encryption_mode.clone();
336→            let pk = fs.private_key.clone();
337→            fs.prefetching.insert(cid.clone());
338→
339→            rt.spawn(async move {
340→                let result = tokio::time::timeout(
341→                    CONTENT_DOWNLOAD_TIMEOUT,
342→                    fetch_and_decrypt_content_async(
343→                        &api, &cid_clone, &efk, &iv_clone, &enc_mode, &pk,
344→                    ),
345→                )
346→                .await;
347→
348→                match result {
349→                    Ok(Ok(plaintext)) => {
350→                        let _ = tx.send(crate::fuse::PendingContent::Success {
351→                            cid: cid_clone,
352→                            data: plaintext,
353→                        });
354→                    }
355→                    Ok(Err(e)) => {
356→                        log::error!("Read prefetch failed for CID {}: {}", cid_clone, e);
357→                        let _ = tx.send(crate::fuse::PendingContent::Failure { cid: cid_clone });
358→                    }
359→                    Err(_) => {
360→                        let _ = tx.send(crate::fuse::PendingContent::Failure { cid: cid_clone });
361→                    }
362→                }
363→            });
364→        }
365→
366→        // Poll for content (up to 5s)
367→        let poll_start = std::time::Instant::now();
368→        let max_wait = Duration::from_secs(5);
369→        loop {
370→            drop(fs);
371→            std::thread::sleep(Duration::from_millis(100));
372→            fs = ctx.inner.lock().unwrap();
373→            fs.drain_content_prefetches();
374→
375→            if let Some(cached) = fs.content_cache.get(&cid) {
376→                let start = offset as usize;
377→                if start >= cached.len() {
378→                    return Ok(0);
379→                }
380→                let end = std::cmp::min(start + buffer.len(), cached.len());
381→                let len = end - start;
382→                buffer[..len].copy_from_slice(&cached[start..end]);
383→                return Ok(len as u32);
384→            }
385→            if poll_start.elapsed() > max_wait {
386→                break;
387→            }
388→        }
389→
390→        Err(status_io_device_error())
391→    }
