393→    /// get_file_info handler
394→    pub fn handle_get_file_info(
395→        ctx: &WinFspContext,
396→        context: &WinFspFileContext,
397→        file_info: &mut FileInfo,
398→    ) -> Result<(), FspError> {
399→        let fs = ctx.inner.lock().unwrap();
400→        let inode = fs
401→            .inodes
402→            .get(context.ino)
403→            .ok_or(status_object_name_not_found())?;
404→        *file_info = fill_file_info(&inode.attr);
405→        Ok(())
406→    }
