408→    /// get_security handler
409→    pub fn handle_get_security(
410→        security_descriptor: Option<&mut [c_void]>,
411→    ) -> Result<u64, FspError> {
412→        if let Some(buf) = security_descriptor {
413→            if buf.len() >= PERMISSIVE_SD.len() {
414→                unsafe {
415→                    std::ptr::copy_nonoverlapping(
416→                        PERMISSIVE_SD.as_ptr(),
417→                        buf.as_mut_ptr() as *mut u8,
418→                        PERMISSIVE_SD.len(),
419→                    );
420→                }
421→            }
422→        }
423→        Ok(PERMISSIVE_SD.len() as u64)
424→    }
425→
426→    /// flush handler
427→    pub fn handle_flush() -> Result<(), FspError> {
428→        Ok(())
429→    }
430→}
