  1→//! Write operations for Windows WinFsp filesystem.
  2→//!
  3→//! Contains handler logic for: create, write, overwrite, cleanup,
  4→//! set_basic_info, set_file_size, set_delete, rename.
  5→
  6→#[cfg(feature = "winfsp")]
  7→pub(crate) mod implementation {
  8→    use std::ffi::c_void;
  9→    use std::sync::atomic::Ordering;
 10→    use std::time::{SystemTime, UNIX_EPOCH};
 11→
 12→    use winfsp::filesystem::{FileInfo, OpenFileInfo};
 13→    use widestring::U16CStr;
 14→    use winfsp::FspError;
 15→
 16→    use crate::fuse::constants::{MAX_VERSIONS_PER_FILE, VERSION_COOLDOWN_MS};
 17→    use crate::fuse::file_handle::OpenFileHandle;
 18→    use crate::fuse::helpers::mime_from_extension;
 19→    use crate::fuse::inode::{FileAttrs, InodeData, InodeKind, ROOT_INO};
 20→    use crate::fuse::windows::operations::implementation::{
 21→        WinFspContext, WinFspFileContext,
 22→        status_object_name_not_found, status_invalid_parameter,
 23→        status_object_name_collision, status_directory_not_empty,
 24→        status_invalid_handle, status_io_device_error,
 25→        resolve_path, split_path, fill_file_info,
 26→        filetime_to_systemtime, publish_file_metadata,
 27→        is_windows_special,
 28→    };
 29→
 30→    /// create handler (files and directories)
 31→    pub fn handle_create(
 32→        ctx: &WinFspContext,
 33→        file_name: &U16CStr,
 34→        create_options: u32,
 35→        granted_access: u32,
 36→        _file_attributes: u32,
 37→        _security_descriptor: Option<&[c_void]>,
 38→        _allocation_size: u64,
 39→        _extra_buffer: Option<&[u8]>,
 40→        _extra_buffer_is_reparse_point: bool,
 41→        file_info: &mut OpenFileInfo,
 42→    ) -> Result<WinFspFileContext, FspError> {
 43→        let path = file_name.to_string_lossy();
 44→        log::info!(
 45→            "create() path={} create_options=0x{:08X} granted_access=0x{:08X}",
 46→            path, create_options, granted_access
 47→        );
 48→        let (parent_path, name) = split_path(&path);
 49→
 50→        if name.is_empty() {
 51→            return Err(status_invalid_parameter());
 52→        }
 53→
 54→        if is_windows_special(name) {
 55→            return Err(status_object_name_not_found());
 56→        }
 57→
 58→        let mut fs = ctx.inner.lock().unwrap();
 59→
 60→        let (parent_ino, _) = resolve_path(&fs, parent_path)
 61→            .ok_or(status_object_name_not_found())?;
 62→
 63→        let parent_is_dir = fs.inodes.get(parent_ino).map(|inode| {
 64→            matches!(inode.kind, InodeKind::Root { .. } | InodeKind::Folder { .. })
 65→        });
 66→        if parent_is_dir != Some(true) {
 67→            return Err(status_object_name_not_found());
 68→        }
 69→
 70→        // FILE_DIRECTORY_FILE = 0x00000001
 71→        let is_dir = (create_options & 0x00000001) != 0;
 72→
 73→        if is_dir {
 74→            // Create directory
 75→            let result = (|| -> Result<(FileAttrs, u64), String> {
 76→                let folder_key = cipherbox_crypto::utils::generate_file_key();
 77→                let (ipns_public_key, ipns_private_key) =
 78→                    cipherbox_crypto::ed25519::generate_ed25519_keypair();
 79→                let ipns_pub_arr: [u8; 32] = ipns_public_key.clone().try_into()
 80→                    .map_err(|_| "Invalid IPNS public key length".to_string())?;
 81→                let ipns_name = cipherbox_core::ipns::derive_ipns_name(&ipns_pub_arr)
 82→                    .map_err(|e| format!("Failed to derive IPNS name: {}", e))?;
 83→                let wrapped_folder_key = cipherbox_crypto::ecies::wrap_key(
 84→                    &folder_key, &fs.public_key,
 85→                )
 86→                .map_err(|e| format!("Folder key wrapping failed: {}", e))?;
 87→                let encrypted_folder_key_hex = hex::encode(&wrapped_folder_key);
 88→
 89→                let ino = fs.inodes.allocate_ino();
 90→                let now = SystemTime::now();
 91→
 92→                let attr = FileAttrs {
 93→                    ino, size: 0, blocks: 0,
 94→                    atime: now, mtime: now, ctime: now, crtime: now,
 95→                    is_dir: true, perm: 0o755, nlink: 2,
 96→                };
 97→
 98→                let inode = InodeData {
 99→                    ino, parent_ino,
100→                    name: name.to_string(),
101→                    kind: InodeKind::Folder {
102→                        ipns_name: ipns_name.clone(),
103→                        encrypted_folder_key: encrypted_folder_key_hex,
104→                        folder_key: zeroize::Zeroizing::new(folder_key.to_vec()),
105→                        ipns_private_key: Some(zeroize::Zeroizing::new(ipns_private_key.clone())),
106→                        children_loaded: true,
107→                    },
108→                    attr: attr.clone(),
109→                    children: Some(vec![]),
110→                    write_generation: 0,
111→                };
112→
113→                fs.inodes.insert(inode);
114→                if let Some(parent_inode) = fs.inodes.get_mut(parent_ino) {
115→                    if let Some(ref mut children) = parent_inode.children {
116→                        children.push(ino);
117→                    }
118→                    parent_inode.attr.mtime = SystemTime::now();
119→                    parent_inode.attr.ctime = SystemTime::now();
120→                }
121→
122→                let metadata = cipherbox_core::folder::FolderMetadata {
123→                    version: "v2".to_string(),
124→                    children: vec![],
125→                };
126→                let json_bytes = crate::fuse::encrypt_metadata_to_json(&metadata, &folder_key)?;
127→                let encrypted_ipns_for_tee = if let Some(ref tee_key) = fs.tee_public_key {
128→                    let wrapped = cipherbox_crypto::ecies::wrap_key(&ipns_private_key, tee_key)
129→                        .map_err(|e| format!("TEE key wrapping failed: {}", e))?;
130→                    Some(hex::encode(&wrapped))
131→                } else {
132→                    None
133→                };
134→                let tee_key_epoch = fs.tee_key_epoch;
135→                let (parent_metadata, parent_folder_key, parent_ipns_key, parent_ipns_name, parent_old_cid) =
136→                    fs.build_folder_metadata(parent_ino)?;
137→
138→                let api = fs.api.clone();
139→                let rt = fs.rt.clone();
140→                let ipns_name_clone = ipns_name.clone();
141→                let coordinator = fs.publish_coordinator.clone();
142→
143→                std::thread::spawn(move || {
144→                    let result = rt.block_on(async {
145→                        let initial_cid = cipherbox_api_client::ipfs::upload_content(&api, &json_bytes).await.map_err(|e| e.to_string())?;
146→                        let ipns_key_arr: [u8; 32] = ipns_private_key.try_into()
147→                            .map_err(|_| "Invalid IPNS key length".to_string())?;
148→                        let value = format!("/ipfs/{}", initial_cid);
149→                        let record = cipherbox_core::ipns::create_ipns_record(
150→                            &ipns_key_arr, &value, 0, 86_400_000,
151→                        ).map_err(|e| format!("IPNS record creation failed: {}", e))?;
152→                        let marshaled = cipherbox_core::ipns::marshal_ipns_record(&record)
153→                            .map_err(|e| format!("IPNS marshal failed: {}", e))?;
154→
155→                        use base64::Engine;
156→                        let record_b64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);
157→                        // New folder initial publish: sequence 0, no conflict check needed
158→                        let req = cipherbox_api_client::IpnsPublishRequest {
159→                            ipns_name: ipns_name_clone.clone(),
160→                            record: record_b64,
161→                            metadata_cid: initial_cid,
162→                            encrypted_ipns_private_key: encrypted_ipns_for_tee,
163→                            key_epoch: tee_key_epoch,
164→                            expected_sequence_number: None,
165→                        };
166→                        match cipherbox_api_client::ipns::publish_ipns(&api, &req).await.map_err(|e| e.to_string())? {
167→                            cipherbox_api_client::PublishResult::Success => {
168→                                coordinator.record_publish(&ipns_name_clone, 0);
169→                            }
170→                            cipherbox_api_client::PublishResult::Conflict { .. } => {
171→                                log::warn!("Unexpected conflict on new folder IPNS publish for {}", ipns_name_clone);
172→                            }
173→                        }
174→
175→                        let lock = coordinator.get_lock(&parent_ipns_name);
176→                        let _guard = lock.lock().await;
177→                        let parent_json = crate::fuse::encrypt_metadata_to_json(
178→                            &parent_metadata, &parent_folder_key,
179→                        )?;
180→                        let seq = coordinator.resolve_sequence(&api, &parent_ipns_name).await?;
181→                        let parent_meta_cid = cipherbox_api_client::ipfs::upload_content(&api, &parent_json).await.map_err(|e| e.to_string())?;
182→                        let parent_key_arr: [u8; 32] = parent_ipns_key.try_into()
183→                            .map_err(|_| "Invalid parent IPNS key length".to_string())?;
184→                        let new_seq = seq + 1;
185→                        let parent_value = format!("/ipfs/{}", parent_meta_cid);
186→                        let parent_record = cipherbox_core::ipns::create_ipns_record(
187→                            &parent_key_arr, &parent_value, new_seq, 86_400_000,
188→                        ).map_err(|e| format!("Parent IPNS record failed: {}", e))?;
189→                        let parent_marshaled = cipherbox_core::ipns::marshal_ipns_record(&parent_record)
190→                            .map_err(|e| format!("Parent IPNS marshal failed: {}", e))?;
191→                        let parent_record_b64 = base64::engine::general_purpose::STANDARD.encode(&parent_marshaled);
192→                        // Parent folder publish after mkdir includes conflict detection.
193→                        // On conflict, log a warning -- the debounced publish queue will retry.
194→                        // TODO: Add full re-fetch+merge+retry for parent mkdir publish (v2).
195→                        let parent_req = cipherbox_api_client::IpnsPublishRequest {
196→                            ipns_name: parent_ipns_name.clone(),
197→                            record: parent_record_b64,
198→                            metadata_cid: parent_meta_cid,
199→                            encrypted_ipns_private_key: None,
200→                            key_epoch: None,
201→                            expected_sequence_number: Some(seq.to_string()),
202→                        };
203→                        match cipherbox_api_client::ipns::publish_ipns(&api, &parent_req).await.map_err(|e| e.to_string())? {
204→                            cipherbox_api_client::PublishResult::Success => {
205→                                coordinator.record_publish(&parent_ipns_name, new_seq);
206→                                // Only unpin old CID on successful publish
207→                                if let Some(old) = parent_old_cid {
208→                                    let _ = cipherbox_api_client::ipfs::unpin_content(&api, &old).await;
209→                                }
210→                            }
211→                            cipherbox_api_client::PublishResult::Conflict { current_sequence_number } => {
212→                                log::warn!(
213→                                    "Conflict on parent publish after mkdir (expected seq {}, server has {}). \
214→                                    Debounced publish will retry.",
215→                                    seq, current_sequence_number
216→                                );
217→                                // Do not unpin -- let the next debounced publish pick up fresh seq
218→                            }
219→                        }
220→                        Ok::<(), String>(())
221→                    });
222→                    if let Err(e) = result {
223→                        log::error!("Background mkdir publish failed: {}", e);
224→                    }
225→                });
226→
227→                Ok((attr, ino))
228→            })();
229→
230→            match result {
231→                Ok((attr, ino)) => {
232→                    *file_info.as_mut() = fill_file_info(&attr);
233→                    let fh = fs.next_fh.fetch_add(1, Ordering::SeqCst);
234→                    Ok(WinFspFileContext { fh, ino, is_dir: true })
235→                }
236→                Err(e) => {
237→                    log::error!("create dir failed: {}", e);
238→                    Err(status_io_device_error())
239→                }
240→            }
241→        } else {
242→            // Create file
243→            let ino = fs.inodes.allocate_ino();
244→            let now = SystemTime::now();
245→
246→            let attr = FileAttrs {
247→                ino, size: 0, blocks: 0,
248→                atime: now, mtime: now, ctime: now, crtime: now,
249→                is_dir: false, perm: 0o644, nlink: 1,
250→            };
251→
252→            let signing_key = ed25519_dalek::SigningKey::generate(&mut rand::rngs::OsRng);
253→            let verifying_key = signing_key.verifying_key();
254→            let file_ipns_private_key = signing_key.to_bytes().to_vec();
255→            let file_ipns_public_key_bytes: [u8; 32] = verifying_key.to_bytes();
256→            let file_ipns_name = match cipherbox_core::ipns::derive_ipns_name(&file_ipns_public_key_bytes) {
257→                Ok(name) => name,
258→                Err(e) => {
259→                    log::error!("create: IPNS name derivation failed: {}", e);
260→                    return Err(status_io_device_error());
261→                }
262→            };
263→
264→            let ipns_key_encrypted_hex = match cipherbox_crypto::ecies::wrap_key(
265→                &file_ipns_private_key, &fs.public_key,
266→            ) {
267→                Ok(wrapped) => Some(hex::encode(&wrapped)),
268→                Err(e) => {
269→                    log::error!("create: failed to ECIES-wrap IPNS key: {}", e);
270→                    return Err(status_io_device_error());
271→                }
272→            };
273→
274→            let inode = InodeData {
275→                ino, parent_ino,
276→                name: name.to_string(),
277→                kind: InodeKind::File {
278→                    cid: String::new(),
279→                    encrypted_file_key: String::new(),
280→                    iv: String::new(),
281→                    size: 0,
282→                    encryption_mode: "GCM".to_string(),
283→                    file_meta_ipns_name: Some(file_ipns_name),
284→                    file_meta_resolved: true,
285→                    file_ipns_private_key: Some(zeroize::Zeroizing::new(file_ipns_private_key)),
286→                    file_ipns_key_encrypted_hex: ipns_key_encrypted_hex,
287→                    versions: None,
288→                },
289→                attr: attr.clone(),
290→                children: None,
291→                write_generation: 0,
292→            };
293→
294→            fs.inodes.insert(inode);
295→            if let Some(parent_inode) = fs.inodes.get_mut(parent_ino) {
296→                if let Some(ref mut children) = parent_inode.children {
297→                    children.push(ino);
298→                }
299→                parent_inode.attr.mtime = SystemTime::now();
300→                parent_inode.attr.ctime = SystemTime::now();
301→            }
302→
303→            let fh = fs.next_fh.fetch_add(1, Ordering::SeqCst);
304→            match OpenFileHandle::new_write(ino, &fs.temp_dir, None) {
305→                Ok(handle) => {
306→                    fs.open_files.insert(fh, handle);
307→                }
308→                Err(e) => {
309→                    log::error!("Failed to create temp file for new file: {}", e);
310→                    fs.inodes.remove(ino);
311→                    return Err(status_io_device_error());
312→                }
313→            }
314→
315→            fs.mutated_folders.insert(parent_ino, std::time::Instant::now());
316→
317→            *file_info.as_mut() = fill_file_info(&attr);
318→            Ok(WinFspFileContext { fh, ino, is_dir: false })
319→        }
320→    }
321→
322→    /// write handler
323→    pub fn handle_write(
324→        ctx: &WinFspContext,
325→        context: &WinFspFileContext,
326→        buffer: &[u8],
327→        offset: u64,
328→        write_to_end_of_file: bool,
329→        file_info: &mut FileInfo,
330→    ) -> Result<u32, FspError> {
331→        let mut fs = ctx.inner.lock().unwrap();
332→        let fh = context.fh;
333→        let ino = context.ino;
334→
335→        let current_file_size = fs.inodes.get(ino).map(|i| i.attr.size).unwrap_or(0);
336→
337→        let actual_offset = if write_to_end_of_file {
338→            log::info!(
339→                "write() ino={} fh={} len={} write_to_end_of_file=true offset_param={} using file_size={}",
340→                ino, fh, buffer.len(), offset, current_file_size
341→            );
342→            current_file_size
343→        } else {
344→            log::info!(
345→                "write() ino={} fh={} len={} offset={} write_to_end_of_file=false",
346→                ino, fh, buffer.len(), offset
347→            );
348→            offset
349→        };
350→
351→        let handle = match fs.open_files.get_mut(&fh) {
352→            Some(h) => h,
353→            None => return Err(status_invalid_handle()),
354→        };
355→
356→        match handle.write_at(actual_offset as i64, buffer) {
357→            Ok(written) => {
358→                let new_end = actual_offset + buffer.len() as u64;
359→                if let Some(inode) = fs.inodes.get_mut(ino) {
360→                    if new_end > inode.attr.size {
361→                        inode.attr.size = new_end;
362→                        inode.attr.blocks = (new_end + 511) / 512;
363→                    }
364→                    inode.attr.mtime = SystemTime::now();
365→                    *file_info = fill_file_info(&inode.attr);
366→                }
367→                Ok(written as u32)
368→            }
369→            Err(e) => {
370→                log::error!("Write failed for ino {} fh {}: {}", ino, fh, e);
371→                Err(status_io_device_error())
372→            }
373→        }
374→    }
375→
376→    /// overwrite handler
377→    pub fn handle_overwrite(
378→        ctx: &WinFspContext,
379→        context: &WinFspFileContext,
380→        file_info: &mut FileInfo,
381→    ) -> Result<(), FspError> {
382→        log::info!("overwrite() called for ino={} fh={}", context.ino, context.fh);
383→        let mut fs = ctx.inner.lock().unwrap();
384→
385→        if let Some(handle) = fs.open_files.get_mut(&context.fh) {
386→            let has_temp = handle.temp_path.is_some();
387→            log::info!("overwrite: handle found, has_temp_path={}", has_temp);
388→            if has_temp {
389→                handle.truncate(0).map_err(|_| status_io_device_error())?;
390→                handle.dirty = true;
391→                log::info!("overwrite: truncated to 0");
392→            }
393→        } else {
394→            log::warn!("overwrite: no handle found for fh={}", context.fh);
395→        }
396→
397→        if let Some(inode) = fs.inodes.get_mut(context.ino) {
398→            inode.attr.size = 0;
399→            inode.attr.mtime = SystemTime::now();
400→            inode.attr.ctime = SystemTime::now();
401→            inode.write_generation += 1;
402→            if let InodeKind::File { size: ref mut s, cid: ref mut c, .. } = inode.kind {
403→                *s = 0;
404→                c.clear();
405→            }
406→            *file_info = fill_file_info(&inode.attr);
407→        }
408→
409→        Ok(())
410→    }
