412→    /// set_basic_info handler
413→    pub fn handle_set_basic_info(
414→        ctx: &WinFspContext,
415→        context: &WinFspFileContext,
416→        creation_time: u64,
417→        last_access_time: u64,
418→        last_write_time: u64,
419→        change_time: u64,
420→        file_info: &mut FileInfo,
421→    ) -> Result<(), FspError> {
422→        let mut fs = ctx.inner.lock().unwrap();
423→        if let Some(inode) = fs.inodes.get_mut(context.ino) {
424→            if creation_time != 0 {
425→                inode.attr.crtime = filetime_to_systemtime(creation_time);
426→            }
427→            if last_access_time != 0 {
428→                inode.attr.atime = filetime_to_systemtime(last_access_time);
429→            }
430→            if last_write_time != 0 {
431→                inode.attr.mtime = filetime_to_systemtime(last_write_time);
432→            }
433→            if change_time != 0 {
434→                inode.attr.ctime = filetime_to_systemtime(change_time);
435→            }
436→            *file_info = fill_file_info(&inode.attr);
437→        }
438→        Ok(())
439→    }
