441→    /// set_file_size handler
442→    pub fn handle_set_file_size(
443→        ctx: &WinFspContext,
444→        context: &WinFspFileContext,
445→        new_size: u64,
446→        set_allocation_size: bool,
447→        file_info: &mut FileInfo,
448→    ) -> Result<(), FspError> {
449→        log::info!(
450→            "set_file_size() ino={} fh={} new_size={} set_allocation_size={}",
451→            context.ino, context.fh, new_size, set_allocation_size
452→        );
453→        let mut fs = ctx.inner.lock().unwrap();
454→
455→        let should_truncate = !set_allocation_size
456→            || (set_allocation_size && new_size == 0);
457→
458→        if should_truncate {
459→            if let Some(handle) = fs.open_files.get_mut(&context.fh) {
460→                if handle.temp_path.is_some() {
461→                    handle.truncate(new_size).map_err(|_| status_io_device_error())?;
462→                    handle.dirty = true;
463→                    log::info!("set_file_size: truncated temp file to {} bytes", new_size);
464→                }
465→            }
466→
467→            if let Some(inode) = fs.inodes.get_mut(context.ino) {
468→                inode.attr.size = new_size;
469→                inode.attr.blocks = (new_size + 511) / 512;
470→                inode.attr.mtime = SystemTime::now();
471→                if new_size == 0 {
472→                    inode.write_generation += 1;
473→                }
474→                if let InodeKind::File { size: ref mut s, cid: ref mut c, .. } = inode.kind {
475→                    *s = new_size;
476→                    if new_size == 0 {
477→                        c.clear();
478→                    }
479→                }
480→                *file_info = fill_file_info(&inode.attr);
481→            }
482→        }
483→
484→        Ok(())
485→    }
