487→    /// cleanup handler (IRP_MJ_CLEANUP -- immediate on handle close)
488→    pub fn handle_cleanup(
489→        ctx: &WinFspContext,
490→        context: &WinFspFileContext,
491→        flags: u32,
492→    ) {
493→        log::info!(
494→            "cleanup() ino={} fh={} flags=0x{:08X}",
495→            context.ino, context.fh, flags
496→        );
497→        let mut fs = ctx.inner.lock().unwrap();
498→        let ino = context.ino;
499→        let fh = context.fh;
500→
501→        // FspCleanupDelete = 0x01
502→        if flags & 0x01 != 0 {
503→            let now = SystemTime::now();
504→            let now_ms = now
505→                .duration_since(UNIX_EPOCH)
506→                .unwrap_or_default()
507→                .as_millis() as u64;
508→
509→            // Capture parent inode and bin entry data before inode removal
510→            let parent_ino = match fs.inodes.get(ino) {
511→                Some(inode) => inode.parent_ino,
512→                None => return,
513→            };
514→
515→            // Capture bin entry data for file or folder before removal
516→            let bin_file_data: Option<(String, u64, cipherbox_core::folder::FilePointer, String, Option<Vec<cipherbox_core::bin::VersionCidEntry>>)> =
517→                match fs.inodes.get(ino) {
518→                    Some(inode) => match &inode.kind {
519→                        InodeKind::File {
520→                            file_meta_ipns_name,
521→                            file_ipns_key_encrypted_hex,
522→                            size,
523→                            cid,
524→                            versions,
525→                            ..
526→                        } => {
527→                            let created_ms = inode.attr.crtime
528→                                .duration_since(UNIX_EPOCH)
529→                                .unwrap_or_default()
530→                                .as_millis() as u64;
531→
532→                            match file_meta_ipns_name {
533→                                Some(name) if !name.is_empty() => {
534→                                    let file_pointer = cipherbox_core::folder::FilePointer {
535→                                        id: cipherbox_crypto::utils::generate_uuid_v4(),
536→                                        name: inode.name.clone(),
537→                                        file_meta_ipns_name: name.clone(),
538→                                        ipns_private_key_encrypted: file_ipns_key_encrypted_hex.clone(),
539→                                        created_at: if created_ms > 0 { created_ms } else { now_ms },
540→                                        modified_at: now_ms,
541→                                    };
542→                                    let ver_cids = crate::fuse::helpers::versions_to_bin_entries(versions);
543→                                    Some((inode.name.clone(), *size, file_pointer, cid.clone(), ver_cids))
544→                                }
545→                                _ => {
546→                                    log::warn!(
547→                                        "cleanup delete: missing file_meta_ipns_name for ino {}, skipping bin entry",
548→                                        ino
549→                                    );
550→                                    None
551→                                }
552→                            }
553→                        }
554→                        _ => None,
555→                    },
556→                    None => None,
557→                };
558→
559→            let bin_folder_data: Option<(String, cipherbox_core::folder::FolderEntry)> =
560→                if bin_file_data.is_none() {
561→                    match fs.inodes.get(ino) {
562→                        Some(inode) => match &inode.kind {
563→                            InodeKind::Folder {
564→                                ipns_name,
565→                                encrypted_folder_key,
566→                                ipns_private_key,
567→                                ..
568→                            } => {
569→                                let created_ms = inode.attr.crtime
570→                                    .duration_since(UNIX_EPOCH)
571→                                    .unwrap_or_default()
572→                                    .as_millis() as u64;
573→
574→                                match ipns_private_key {
575→                                    Some(key) => {
576→                                        match cipherbox_crypto::ecies::wrap_key(key, &fs.public_key) {
577→                                            Ok(wrapped) => {
578→                                                let folder_entry = cipherbox_core::folder::FolderEntry {
579→                                                    id: cipherbox_crypto::utils::generate_uuid_v4(),
580→                                                    name: inode.name.clone(),
581→                                                    ipns_name: ipns_name.clone(),
582→                                                    folder_key_encrypted: encrypted_folder_key.clone(),
583→                                                    ipns_private_key_encrypted: hex::encode(&wrapped),
584→                                                    created_at: if created_ms > 0 { created_ms } else { now_ms },
585→                                                    modified_at: now_ms,
586→                                                };
587→                                                Some((inode.name.clone(), folder_entry))
588→                                            }
589→                                            Err(e) => {
590→                                                log::error!("cleanup delete: failed to wrap IPNS key: {}", e);
591→                                                None
592→                                            }
593→                                        }
594→                                    }
595→                                    None => {
596→                                        log::error!("cleanup delete: missing IPNS private key for ino {}", ino);
597→                                        None
598→                                    }
599→                                }
600→                            }
601→                            _ => None,
602→                        },
603→                        None => None,
604→                    }
605→                } else {
606→                    None
607→                };
608→
609→            fs.inodes.remove(ino);
610→
611→            if let Some(parent_inode) = fs.inodes.get_mut(parent_ino) {
612→                parent_inode.attr.mtime = now;
613→                parent_inode.attr.ctime = now;
614→            }
615→
616→            if let Err(e) = fs.update_folder_metadata(parent_ino) {
617→                log::error!("Failed to update folder metadata after delete: {}", e);
618→            }
619→
620→            // Create bin entry and publish (fire-and-forget) -- CIDs stay pinned for recovery
621→            let parent_ipns_name = fs.inodes.get(parent_ino)
622→                .map(|p| match &p.kind {
623→                    InodeKind::Root { ipns_name, .. } => ipns_name.clone().unwrap_or_default(),
624→                    InodeKind::Folder { ipns_name, .. } => ipns_name.clone(),
625→                    _ => String::new(),
626→                })
627→                .unwrap_or_default();
628→
629→            if !parent_ipns_name.is_empty() {
630→                let parent_path = crate::fuse::helpers::build_folder_path(&fs, parent_ino);
631→
632→                let bin_entry = if let Some((name, size, fp, cid, ver_cids)) = bin_file_data {
633→                    Some(cipherbox_core::bin::BinEntry {
634→                        id: cipherbox_crypto::utils::generate_uuid_v4(),
635→                        item_type: cipherbox_core::bin::BinItemType::File,
636→                        name: name.clone(),
637→                        original_parent_ipns_name: parent_ipns_name,
638→                        original_path: parent_path,
639→                        deleted_at: now_ms,
640→                        size,
641→                        mime_type: cipherbox_crypto::utils::mime_from_extension(&name).to_string(),
642→                        content_cid: if cid.is_empty() { None } else { Some(cid) },
643→                        content_size: Some(size),
644→                        version_cids: ver_cids,
645→                        file_pointer: Some(fp),
646→                        folder_entry: None,
647→                    })
648→                } else if let Some((name, fe)) = bin_folder_data {
649→                    Some(cipherbox_core::bin::BinEntry {
650→                        id: cipherbox_crypto::utils::generate_uuid_v4(),
651→                        item_type: cipherbox_core::bin::BinItemType::Folder,
652→                        name,
653→                        original_parent_ipns_name: parent_ipns_name,
654→                        original_path: parent_path,
655→                        deleted_at: now_ms,
656→                        size: 0,
657→                        mime_type: String::new(),
658→                        content_cid: None,
659→                        content_size: None,
660→                        version_cids: None,
661→                        file_pointer: None,
662→                        folder_entry: Some(fe),
663→                    })
664→                } else {
665→                    None
666→                };
667→
668→                if let Some(entry) = bin_entry {
669→                    crate::fuse::spawn_bin_entry_publish(
670→                        fs.api.clone(),
671→                        fs.rt.clone(),
672→                        entry,
673→                        fs.private_key.clone(),
674→                        fs.public_key.to_vec(),
675→                        fs.publish_coordinator.clone(),
676→                    );
677→                }
678→            } else {
679→                log::warn!(
680→                    "cleanup delete: missing parent IPNS name for parent ino {}, skipping bin publish",
681→                    parent_ino
682→                );
683→            }
684→        } else {
685→            // Non-delete cleanup: flush dirty file handles
686→            fs.drain_upload_completions();
687→
688→            let needs_flush = fs.open_files.get(&fh)
689→                .map(|h| {
690→                    let has_temp = h.temp_path.is_some();
691→                    let is_new = has_temp && fs.inodes.get(ino)
692→                        .map(|i| match &i.kind {
693→                            InodeKind::File { cid, .. } => cid.is_empty(),
694→                            _ => false,
695→                        })
696→                        .unwrap_or(false);
697→                    has_temp && (h.dirty || is_new)
698→                })
699→                .unwrap_or(false);
700→
701→            if needs_flush {
702→                let handle = fs.open_files.remove(&fh).unwrap();
703→
704→                let prepare_result = (|| -> Result<(), String> {
705→                    let plaintext = handle.read_all()?;
706→                    let mut file_key = cipherbox_crypto::utils::generate_file_key();
707→                    let iv = cipherbox_crypto::utils::generate_iv();
708→                    let ciphertext = cipherbox_crypto::aes::encrypt_aes_gcm(
709→                        &plaintext, &file_key, &iv,
710→                    )
711→                    .map_err(|e| format!("File encryption failed: {}", e))?;
712→                    let wrapped_key = cipherbox_crypto::ecies::wrap_key(&file_key, &fs.public_key)
713→                        .map_err(|e| format!("Key wrapping failed: {}", e))?;
714→                    cipherbox_crypto::utils::clear_bytes(&mut file_key);
715→
716→                    let (old_file_cid, _old_encrypted_key, _old_iv, old_size, old_mode,
717→                         existing_versions, file_ipns_private_key, file_meta_ipns_name) =
718→                        fs.inodes.get(ino).map(|inode| match &inode.kind {
719→                            InodeKind::File {
720→                                cid, encrypted_file_key, iv, size, encryption_mode,
721→                                versions, file_ipns_private_key, file_meta_ipns_name, ..
722→                            } => (
723→                                if cid.is_empty() { None } else { Some(cid.clone()) },
724→                                encrypted_file_key.clone(), iv.clone(), *size,
725→                                encryption_mode.clone(), versions.clone(),
726→                                file_ipns_private_key.clone(), file_meta_ipns_name.clone(),
727→                            ),
728→                            _ => (None, String::new(), String::new(), 0, "GCM".to_string(), None, None, None),
729→                        }).unwrap_or((None, String::new(), String::new(), 0, "GCM".to_string(), None, None, None));
730→
731→                    let encrypted_file_key_hex = hex::encode(&wrapped_key);
732→                    let iv_hex = hex::encode(&iv);
733→                    let file_size = plaintext.len() as u64;
734→                    let file_name = fs.inodes.get(ino).map(|i| i.name.clone()).unwrap_or_default();
735→                    let mime_type = mime_from_extension(&file_name);
736→
737→                    let now_ms = SystemTime::now()
738→                        .duration_since(UNIX_EPOCH)
739→                        .unwrap_or_default()
740→                        .as_millis() as u64;
741→
742→                    let should_version = if let Some(ref versions) = existing_versions {
743→                        if let Some(newest) = versions.first() {
744→                            now_ms.saturating_sub(newest.timestamp) >= VERSION_COOLDOWN_MS
745→                        } else {
746→                            old_file_cid.as_ref().is_some_and(|c| !c.is_empty())
747→                        }
748→                    } else {
749→                        old_file_cid.as_ref().is_some_and(|c| !c.is_empty())
750→                    };
751→
752→                    let (new_versions, pruned_cids) = if should_version {
753→                        if let Some(ref old_c) = old_file_cid {
754→                            if !old_c.is_empty() {
755→                                let version_entry = cipherbox_core::folder::VersionEntry {
756→                                    cid: old_c.clone(),
757→                                    file_key_encrypted: _old_encrypted_key.clone(),
758→                                    file_iv: _old_iv.clone(),
759→                                    size: old_size,
760→                                    timestamp: now_ms,
761→                                    encryption_mode: old_mode.clone(),
762→                                };
763→                                let mut versions = vec![version_entry];
764→                                versions.extend(existing_versions.unwrap_or_default());
765→                                let pruned: Vec<String> = if versions.len() > MAX_VERSIONS_PER_FILE {
766→                                    versions.split_off(MAX_VERSIONS_PER_FILE).into_iter().map(|v| v.cid).collect()
767→                                } else {
768→                                    vec![]
769→                                };
770→                                (Some(versions), pruned)
771→                            } else {
772→                                (existing_versions, vec![])
773→                            }
774→                        } else {
775→                            (existing_versions, vec![])
776→                        }
777→                    } else {
778→                        (existing_versions, vec![])
779→                    };
780→
781→                    let versions_for_meta = new_versions.as_ref()
782→                        .filter(|v| !v.is_empty())
783→                        .cloned();
784→
785→                    if let Some(inode) = fs.inodes.get_mut(ino) {
786→                        let cached_hex = match &inode.kind {
787→                            InodeKind::File { file_ipns_key_encrypted_hex, .. } => file_ipns_key_encrypted_hex.clone(),
788→                            _ => None,
789→                        };
790→                        inode.kind = InodeKind::File {
791→                            cid: String::new(),
792→                            encrypted_file_key: encrypted_file_key_hex.clone(),
793→                            iv: iv_hex.clone(),
794→                            size: file_size,
795→                            encryption_mode: "GCM".to_string(),
796→                            file_meta_ipns_name: file_meta_ipns_name.clone(),
797→                            file_meta_resolved: true,
798→                            file_ipns_private_key: file_ipns_private_key.clone(),
799→                            file_ipns_key_encrypted_hex: cached_hex,
800→                            versions: versions_for_meta.clone(),
801→                        };
802→                        // Bump generation so stale background uploads (from a
803→                        // prior truncate-to-zero flush) are rejected by
804→                        // drain_upload_completions.
805→                        inode.write_generation += 1;
806→                        inode.attr.size = file_size;
807→                        inode.attr.blocks = (file_size + 511) / 512;
808→                        inode.attr.mtime = SystemTime::now();
809→                    }
810→
811→                    fs.pending_content.insert(ino, plaintext);
812→
813→                    let write_gen = fs.inodes.get(ino)
814→                        .map(|i| i.write_generation)
815→                        .unwrap_or(0);
816→                    let parent_ino = fs.inodes.get(ino).map(|i| i.parent_ino).unwrap_or(ROOT_INO);
817→                    let folder_key_for_file_meta = fs.get_folder_key(parent_ino);
818→                    fs.queue_publish(parent_ino, true);
819→
820→                    let api = fs.api.clone();
821→                    let rt = fs.rt.clone();
822→                    let upload_tx = fs.upload_tx.clone();
823→                    let coordinator = fs.publish_coordinator.clone();
824→
825→                    let file_meta = cipherbox_core::folder::FileMetadata {
826→                        version: "v1".to_string(),
827→                        cid: String::new(),
828→                        file_key_encrypted: encrypted_file_key_hex,
829→                        file_iv: iv_hex,
830→                        size: file_size,
831→                        mime_type,
832→                        encryption_mode: "GCM".to_string(),
833→                        created_at: now_ms,
834→                        modified_at: now_ms,
835→                        versions: versions_for_meta,
836→                    };
837→
838→                    std::thread::spawn(move || {
839→                        let result = rt.block_on(async {
840→                            let file_cid = cipherbox_api_client::ipfs::upload_content(&api, &ciphertext).await.map_err(|e| e.to_string())?;
841→                            log::info!("File uploaded: ino {} -> CID {}", ino, file_cid);
842→
843→                            let _ = upload_tx.send(crate::fuse::UploadComplete {
844→                                ino,
845→                                new_cid: file_cid.clone(),
846→                                parent_ino,
847→                                old_file_cid,
848→                                pruned_cids,
849→                                write_generation: write_gen,
850→                            });
851→
852→                            if let (Some(ipns_key), Some(ipns_name), Some(folder_key)) =
853→                                (&file_ipns_private_key, &file_meta_ipns_name, &folder_key_for_file_meta)
854→                            {
855→                                let mut file_meta_with_cid = file_meta;
856→                                file_meta_with_cid.cid = file_cid;
857→                                if let Err(e) = publish_file_metadata(
858→                                    &api, &file_meta_with_cid, folder_key, ipns_key, ipns_name, &coordinator,
859→                                ).await {
860→                                    log::warn!("Per-file IPNS publish failed for ino {}: {}", ino, e);
861→                                }
862→                            }
863→
864→                            Ok::<(), String>(())
865→                        });
866→
867→                        if let Err(e) = result {
868→                            log::error!("Background upload failed for ino {}: {}", ino, e);
869→                        }
870→                    });
871→
872→                    Ok(())
873→                })();
874→
875→                if let Err(e) = prepare_result {
876→                    log::error!("File upload preparation failed for ino {}: {}", ino, e);
877→                }
878→
879→                handle.cleanup();
880→            }
881→        }
882→    }
883→
884→    /// rename handler
885→    pub fn handle_rename(
886→        ctx: &WinFspContext,
887→        file_name: &U16CStr,
888→        new_file_name: &U16CStr,
889→        replace_if_exists: bool,
890→    ) -> Result<(), FspError> {
891→        let old_path = file_name.to_string_lossy();
892→        let new_path = new_file_name.to_string_lossy();
893→
894→        let mut fs = ctx.inner.lock().unwrap();
895→
896→        let (source_ino, old_parent_ino) = resolve_path(&fs, &old_path)
897→            .ok_or(status_object_name_not_found())?;
898→
899→        let (new_parent_path, new_name) = split_path(&new_path);
900→        let (new_parent_ino, _) = resolve_path(&fs, new_parent_path)
901→            .ok_or(status_object_name_not_found())?;
902→
903→        if let Some(dest_ino) = fs.inodes.find_child(new_parent_ino, new_name) {
904→            if !replace_if_exists {
905→                return Err(status_object_name_collision());
906→            }
907→            if let Some(dest_inode) = fs.inodes.get(dest_ino) {
908→                match &dest_inode.kind {
909→                    InodeKind::Folder { .. } => {
910→                        if let Some(ref children) = dest_inode.children {
911→                            if !children.is_empty() {
912→                                return Err(status_directory_not_empty());
913→                            }
914→                        }
915→                    }
916→                    InodeKind::File { cid, .. } => {
917→                        if !cid.is_empty() {
918→                            let cid_clone = cid.clone();
919→                            let api = fs.api.clone();
920→                            fs.rt.spawn(async move {
921→                                let _ = cipherbox_api_client::ipfs::unpin_content(&api, &cid_clone).await;
922→                            });
923→                        }
924→                    }
925→                    _ => {}
926→                }
927→            }
928→            fs.inodes.remove(dest_ino);
929→        }
930→
931→        let old_name = fs.inodes.get(source_ino).map(|i| i.name.clone()).unwrap_or_default();
932→        fs.inodes.name_to_ino.remove(&(
933→            old_parent_ino,
934→            crate::fuse::inode::normalize_name(&old_name),
935→        ));
936→
937→        if let Some(inode) = fs.inodes.get_mut(source_ino) {
938→            inode.name = new_name.to_string();
939→            inode.parent_ino = new_parent_ino;
940→            inode.attr.ctime = SystemTime::now();
941→        }
942→
943→        fs.inodes.name_to_ino.insert(
944→            (new_parent_ino, crate::fuse::inode::normalize_name(new_name)),
945→            source_ino,
946→        );
947→
948→        if old_parent_ino != new_parent_ino {
949→            if let Some(old_parent) = fs.inodes.get_mut(old_parent_ino) {
950→                if let Some(ref mut children) = old_parent.children {
951→                    children.retain(|&c| c != source_ino);
952→                }
953→                old_parent.attr.mtime = SystemTime::now();
954→                old_parent.attr.ctime = SystemTime::now();
955→            }
956→            if let Some(new_parent) = fs.inodes.get_mut(new_parent_ino) {
957→                if let Some(ref mut children) = new_parent.children {
958→                    children.push(source_ino);
959→                }
960→                new_parent.attr.mtime = SystemTime::now();
961→                new_parent.attr.ctime = SystemTime::now();
962→            }
963→            if let Err(e) = fs.update_folder_metadata(old_parent_ino) {
964→                log::error!("Failed to update old parent metadata after rename: {}", e);
965→            }
966→            if let Err(e) = fs.update_folder_metadata(new_parent_ino) {
967→                log::error!("Failed to update new parent metadata after rename: {}", e);
968→            }
969→        } else {
970→            if let Some(parent_inode) = fs.inodes.get_mut(old_parent_ino) {
971→                parent_inode.attr.mtime = SystemTime::now();
972→                parent_inode.attr.ctime = SystemTime::now();
973→            }
974→            if let Err(e) = fs.update_folder_metadata(old_parent_ino) {
975→                log::error!("Failed to update parent metadata after rename: {}", e);
976→            }
977→        }
978→
979→        Ok(())
980→    }
981→
982→    /// set_delete handler
983→    pub fn handle_set_delete(
984→        context: &WinFspFileContext,
