  1→//! Directory operations for Windows WinFsp filesystem.
  2→//!
  3→//! Contains handler logic for: read_directory.
  4→
  5→#[cfg(feature = "winfsp")]
  6→pub(crate) mod implementation {
  7→    use winfsp::filesystem::{DirInfo, DirMarker, FileInfo, WideNameInfo};
  8→    use widestring::U16CString;
  9→    use winfsp::FspError;
 10→
 11→    use crate::fuse::constants::CONTENT_DOWNLOAD_TIMEOUT;
 12→    use crate::fuse::inode::InodeKind;
 13→    use crate::fuse::windows::operations::implementation::{
 14→        WinFspContext, WinFspFileContext,
 15→        status_object_name_not_found,
 16→        fill_file_info, fetch_and_decrypt_content_async,
 17→        is_windows_special,
 18→    };
 19→
 20→    /// read_directory handler
 21→    pub fn handle_read_directory(
 22→        ctx: &WinFspContext,
 23→        context: &WinFspFileContext,
 24→        marker: DirMarker,
 25→        buffer: &mut [u8],
 26→    ) -> Result<u32, FspError> {
 27→        let mut fs = ctx.inner.lock().unwrap();
 28→        let ino = context.ino;
 29→
 30→        fs.drain_refresh_completions();
 31→        fs.drain_upload_completions();
 32→
 33→        let inode = fs
 34→            .inodes
 35→            .get(ino)
 36→            .ok_or(status_object_name_not_found())?;
 37→
 38→        // Check if metadata is stale and fire background refresh
 39→        let stale_info: Option<(String, zeroize::Zeroizing<Vec<u8>>)> =
 40→            match &inode.kind {
 41→                InodeKind::Root { ipns_name, .. } => {
 42→                    ipns_name.as_ref().and_then(|name| {
 43→                        if fs.metadata_cache.get(name).is_none() {
 44→                            Some((name.clone(), fs.root_folder_key.clone()))
 45→                        } else {
 46→                            None
 47→                        }
 48→                    })
 49→                }
 50→                InodeKind::Folder { ipns_name, folder_key, .. } => {
 51→                    if fs.metadata_cache.get(&ipns_name).is_none() {
 52→                        Some((ipns_name.clone(), folder_key.clone()))
 53→                    } else {
 54→                        None
 55→                    }
 56→                }
 57→                _ => None,
 58→            };
 59→
 60→        if let Some((ipns_name, folder_key)) = stale_info {
 61→            let api = fs.api.clone();
 62→            let rt = fs.rt.clone();
 63→            let tx = fs.refresh_tx.clone();
 64→            let refresh_ino = ino;
 65→            rt.spawn(async move {
 66→                match cipherbox_api_client::ipns::resolve_ipns(&api, &ipns_name).await {
 67→                    Ok(resolve_resp) => {
 68→                        match cipherbox_api_client::ipfs::fetch_content(&api, &resolve_resp.cid).await {
 69→                            Ok(encrypted_bytes) => {
 70→                                match cipherbox_core::decrypt::decrypt_metadata_from_ipfs_public(
 71→                                    &encrypted_bytes, &folder_key,
 72→                                ) {
 73→                                    Ok(metadata) => {
 74→                                        let _ = tx.send(crate::fuse::PendingRefresh {
 75→                                            ino: refresh_ino,
 76→                                            ipns_name,
 77→                                            metadata,
 78→                                            cid: resolve_resp.cid,
 79→                                        });
 80→                                    }
 81→                                    Err(e) => log::warn!("Refresh decrypt failed: {}", e),
 82→                                }
 83→                            }
 84→                            Err(e) => log::warn!("Refresh fetch failed: {}", e),
 85→                        }
 86→                    }
 87→                    Err(e) => log::warn!("Refresh resolve failed for {}: {}", ipns_name, e),
 88→                }
 89→            });
 90→        }
 91→
 92→        let parent_ino = inode.parent_ino;
 93→        let children = inode.children.clone().unwrap_or_default();
 94→
 95→        let mut entries: Vec<(U16CString, FileInfo)> = Vec::new();
 96→
 97→        if let Ok(name) = U16CString::from_str(".") {
 98→            entries.push((name, fill_file_info(&inode.attr)));
 99→        }
100→
101→        if let Some(parent) = fs.inodes.get(parent_ino) {
102→            if let Ok(name) = U16CString::from_str("..") {
103→                entries.push((name, fill_file_info(&parent.attr)));
104→            }
105→        }
106→
107→        for &child_ino in &children {
108→            if let Some(child) = fs.inodes.get(child_ino) {
109→                if is_windows_special(&child.name) {
110→                    continue;
111→                }
112→                if let Ok(name) = U16CString::from_str(&child.name) {
113→                    entries.push((name, fill_file_info(&child.attr)));
114→                }
115→            }
116→        }
117→
118→        let mut past_marker = marker.is_none();
119→        let mut bytes_written: u32 = 0;
120→
121→        for (entry_name, entry_info) in &entries {
122→            if !past_marker {
123→                let entry_str = entry_name.to_string_lossy();
124→                let is_match = if marker.is_current() {
125→                    entry_str == "."
126→                } else if marker.is_parent() {
127→                    entry_str == ".."
128→                } else if let Some(marker_cstr) = marker.inner_as_cstr() {
129→                    entry_str == marker_cstr.to_string_lossy()
130→                } else {
131→                    false
132→                };
133→                if is_match {
134→                    past_marker = true;
135→                }
136→                continue;
137→            }
138→
139→            let mut dir_info = DirInfo::<255>::new();
140→            *dir_info.file_info_mut() = entry_info.clone();
141→            let _ = dir_info.set_name_cstr(entry_name);
142→            if !dir_info.append_to_buffer(buffer, &mut bytes_written) {
143→                break;
144→            }
145→        }
146→
147→        // Proactive content prefetch for child files
148→        fs.drain_content_prefetches();
149→        for &child_ino in &children {
150→            let file_info = fs.inodes.get(child_ino).and_then(|child| {
151→                if let InodeKind::File { cid, encrypted_file_key, iv, encryption_mode, .. } = &child.kind {
152→                    if !cid.is_empty() {
153→                        Some((cid.clone(), encrypted_file_key.clone(), iv.clone(), encryption_mode.clone()))
154→                    } else {
155→                        None
156→                    }
157→                } else {
158→                    None
159→                }
160→            });
161→            if let Some((cid_clone, efk, iv_clone, enc_mode)) = file_info {
162→                if fs.content_cache.get(&cid_clone).is_none()
163→                    && !fs.prefetching.contains(&cid_clone)
164→                {
165→                    let api = fs.api.clone();
166→                    let rt = fs.rt.clone();
167→                    let tx = fs.content_tx.clone();
168→                    let pk = fs.private_key.clone();
169→                    fs.prefetching.insert(cid_clone.clone());
170→
171→                    rt.spawn(async move {
172→                        let result = tokio::time::timeout(
173→                            CONTENT_DOWNLOAD_TIMEOUT,
174→                            fetch_and_decrypt_content_async(
175→                                &api, &cid_clone, &efk, &iv_clone, &enc_mode, &pk,
176→                            ),
177→                        )
178→                        .await;
179→
180→                        match result {
181→                            Ok(Ok(plaintext)) => {
182→                                let _ = tx.send(crate::fuse::PendingContent::Success {
183→                                    cid: cid_clone,
184→                                    data: plaintext,
185→                                });
186→                            }
187→                            Ok(Err(_e)) => {
188→                                let _ = tx.send(crate::fuse::PendingContent::Failure {
189→                                    cid: cid_clone,
190→                                });
191→                            }
192→                            Err(_) => {
193→                                let _ = tx.send(crate::fuse::PendingContent::Failure {
194→                                    cid: cid_clone,
195→                                });
196→                            }
197→                        }
198→                    });
199→                }
200→            }
201→        }
202→
203→        Ok(bytes_written)
204→    }
205→}
