  4→//! All FUSE data structures, operations, and platform logic live in the crate.
  5→//! This module handles Tauri-specific mount orchestration (AppState -> CipherBoxFS).
  6→
  7→// Re-export crate types and functions used by desktop FUSE submodules.
  8→// These are consumed via `crate::fuse::inode::*`, `crate::fuse::helpers::*`, etc.
  9→#[allow(unused_imports)]
 10→#[cfg(any(feature = "fuse", feature = "winfsp"))]
