 45→
 46→/// Mount the FUSE filesystem after successful authentication (macOS/Linux).
 47→#[cfg(feature = "fuse")]
 48→pub async fn mount_filesystem(
 49→    state: &AppState,
 50→    rt: tokio::runtime::Handle,
 51→    private_key: Vec<u8>,
 52→    public_key: Vec<u8>,
 53→    root_folder_key: Vec<u8>,
 54→    root_ipns_name: String,
 55→    root_ipns_private_key: Option<Vec<u8>>,
 56→    tee_public_key: Option<Vec<u8>>,
 57→    tee_key_epoch: Option<u32>,
 58→) -> Result<std::thread::JoinHandle<()>, String> {
 59→    let mount_path = mount_point();
 60→
 61→    if mount_path.is_symlink() {
 62→        return Err("Mount point is a symlink -- refusing to proceed".to_string());
 63→    }
 64→
 65→    if !mount_path.exists() {
 66→        std::fs::create_dir_all(&mount_path)
 67→            .map_err(|e| format!("Failed to create mount point: {}", e))?;
 68→        #[cfg(unix)]
 69→        {
 70→            use std::os::unix::fs::PermissionsExt;
 71→            let _ = std::fs::set_permissions(&mount_path, std::fs::Permissions::from_mode(0o700));
 72→        }
 73→    } else {
 74→        if let Ok(entries) = std::fs::read_dir(&mount_path) {
 75→            for entry in entries.flatten() {
 76→                let path = entry.path();
 77→                if path.is_dir() { let _ = std::fs::remove_dir_all(&path); }
 78→                else { let _ = std::fs::remove_file(&path); }
 79→            }
 80→            log::info!("Cleaned stale mount point: {}", mount_path.display());
 81→        }
 82→    }
 83→
 84→    #[cfg(target_os = "macos")]
 85→    {
 86→        let never_index = mount_path.join(".metadata_never_index");
 87→        if !never_index.exists() { let _ = std::fs::File::create(&never_index); }
 88→    }
 89→
 90→    let temp_dir = std::env::temp_dir().join("cipherbox");
 91→    std::fs::create_dir_all(&temp_dir).map_err(|e| format!("Failed to create temp directory: {}", e))?;
 92→    #[cfg(unix)]
 93→    {
 94→        use std::os::unix::fs::PermissionsExt;
 95→        let _ = std::fs::set_permissions(&temp_dir, std::fs::Permissions::from_mode(0o700));
 96→    }
 97→
 98→    let mut inodes = cipherbox_fuse::inode::InodeTable::new();
 99→    if let Some(root) = inodes.get_mut(cipherbox_fuse::inode::ROOT_INO) {
100→        root.kind = cipherbox_fuse::inode::InodeKind::Root {
101→            ipns_private_key: root_ipns_private_key.map(Zeroizing::new),
102→            ipns_name: Some(root_ipns_name.clone()),
103→        };
104→    }
105→
106→    let (refresh_tx, refresh_rx) = std::sync::mpsc::channel::<PendingRefresh>();
107→    let (content_tx, content_rx) = std::sync::mpsc::channel::<PendingContent>();
108→    let (upload_tx, upload_rx) = std::sync::mpsc::channel::<UploadComplete>();
109→
110→    // Pre-populate root folder
111→    let mut metadata_cache = cipherbox_fuse::cache::MetadataCache::new();
112→    log::info!("Pre-populating root folder from IPNS...");
113→    let fetch_result: Result<(Vec<u8>, String), String> = async {
114→        let resolve_resp = cipherbox_api_client::ipns::resolve_ipns(&state.sdk.api, &root_ipns_name).await.map_err(|e| format!("{}", e))?;
115→        let encrypted_bytes = cipherbox_api_client::ipfs::fetch_content(&state.sdk.api, &resolve_resp.cid).await.map_err(|e| format!("{}", e))?;
116→        Ok((encrypted_bytes, resolve_resp.cid))
117→    }.await;
118→
119→    match fetch_result {
120→        Ok((encrypted_bytes, cid)) => {
121→            match cipherbox_core::decrypt_metadata_from_ipfs_public(&encrypted_bytes, &root_folder_key) {
122→                Ok(metadata) => {
123→                    metadata_cache.set(&root_ipns_name, metadata.clone(), cid);
124→                    if let Ok(()) = inodes.populate_folder(cipherbox_fuse::inode::ROOT_INO, &metadata, &private_key, &public_key, false) {
125→                        log::info!("Root folder pre-populated successfully");
126→                        // Resolve root FilePointers
127→                        let unresolved = inodes.get_unresolved_file_pointers();
128→                        if !unresolved.is_empty() {
129→                            if let Ok(fk) = <[u8; 32]>::try_from(root_folder_key.as_slice()) {
130→                                for (fp_ino, fp_ipns) in &unresolved {
131→                                    let fp_result: Result<Vec<u8>, String> = async {
132→                                        let resp = cipherbox_api_client::ipns::resolve_ipns(&state.sdk.api, fp_ipns).await.map_err(|e| format!("{}", e))?;
133→                                        cipherbox_api_client::ipfs::fetch_content(&state.sdk.api, &resp.cid).await.map_err(|e| format!("{}", e))
134→                                    }.await;
135→                                    if let Ok(enc_bytes) = fp_result {
136→                                        if let Ok(fm) = cipherbox_core::decrypt_file_metadata_from_ipfs_public(&enc_bytes, &fk) {
137→                                            inodes.resolve_file_pointer(*fp_ino, fm.cid, fm.file_key_encrypted, fm.file_iv, fm.size, fm.encryption_mode, fm.versions);
138→                                        }
139→                                    }
140→                                }
141→                            }
142→                        }
143→                        // Pre-populate subfolders
144→                        let subfolder_infos: Vec<(u64, String, Zeroizing<Vec<u8>>)> = inodes.inodes.values()
145→                            .filter_map(|inode| {
146→                                if inode.parent_ino != cipherbox_fuse::inode::ROOT_INO { return None; }
147→                                if let cipherbox_fuse::inode::InodeKind::Folder { ref ipns_name, ref folder_key, .. } = inode.kind {
148→                                    Some((inode.ino, ipns_name.clone(), folder_key.clone()))
149→                                } else { None }
150→                            }).collect();
151→                        for (sub_ino, sub_ipns, sub_key) in &subfolder_infos {
152→                            let sub_result: Result<(Vec<u8>, String), String> = async {
153→                                let resp = cipherbox_api_client::ipns::resolve_ipns(&state.sdk.api, sub_ipns).await.map_err(|e| format!("{}", e))?;
154→                                let bytes = cipherbox_api_client::ipfs::fetch_content(&state.sdk.api, &resp.cid).await.map_err(|e| format!("{}", e))?;
155→                                Ok((bytes, resp.cid))
156→                            }.await;
157→                            if let Ok((enc_bytes, sub_cid)) = sub_result {
158→                                if let Ok(sub_meta) = cipherbox_core::decrypt_metadata_from_ipfs_public(&enc_bytes, sub_key) {
159→                                    metadata_cache.set(sub_ipns, sub_meta.clone(), sub_cid);
160→                                    if let Ok(()) = inodes.populate_folder(*sub_ino, &sub_meta, &private_key, &public_key, false) {
161→                                        let sub_unresolved = inodes.get_unresolved_file_pointers();
162→                                        if let Ok(sk) = <[u8; 32]>::try_from(sub_key.as_slice()) {
163→                                            for (fp_ino, fp_ipns) in &sub_unresolved {
164→                                                let fp_result: Result<Vec<u8>, String> = async {
165→                                                    let resp = cipherbox_api_client::ipns::resolve_ipns(&state.sdk.api, fp_ipns).await.map_err(|e| format!("{}", e))?;
166→                                                    cipherbox_api_client::ipfs::fetch_content(&state.sdk.api, &resp.cid).await.map_err(|e| format!("{}", e))
167→                                                }.await;
168→                                                if let Ok(enc_bytes) = fp_result {
169→                                                    if let Ok(fm) = cipherbox_core::decrypt_file_metadata_from_ipfs_public(&enc_bytes, &sk) {
170→                                                        inodes.resolve_file_pointer(*fp_ino, fm.cid, fm.file_key_encrypted, fm.file_iv, fm.size, fm.encryption_mode, fm.versions);
171→                                                    }
172→                                                }
173→                                            }
174→                                        }
175→                                    }
176→                                }
177→                            }
178→                        }
179→                    }
180→                }
181→                Err(e) => log::warn!("Root metadata decryption failed: {}", e),
182→            }
183→        }
184→        Err(e) => log::warn!("Root folder fetch failed (mount will show empty): {}", e),
185→    }
186→
187→    let fs = CipherBoxFS {
188→        inodes, metadata_cache,
189→        content_cache: cipherbox_fuse::cache::ContentCache::new(),
190→        api: state.sdk.api.clone(),
191→        private_key: Zeroizing::new(private_key),
192→        public_key: Zeroizing::new(public_key),
193→        root_folder_key: Zeroizing::new(root_folder_key),
194→        root_ipns_name, rt,
195→        next_fh: std::sync::atomic::AtomicU64::new(1),
196→        open_files: HashMap::new(),
197→        temp_dir, tee_public_key, tee_key_epoch,
198→        refresh_rx, refresh_tx,
199→        prefetching: std::collections::HashSet::new(),
200→        content_rx, content_tx,
201→        pending_content: HashMap::new(),
202→        upload_rx, upload_tx,
203→        mutated_folders: HashMap::new(),
204→        publish_coordinator: Arc::new(PublishCoordinator::new()),
205→        publish_queue: HashMap::new(),
206→    };
207→
208→    let mount_path_clone = mount_path.clone();
209→
210→    #[cfg(target_os = "linux")]
211→    let options = vec![MountOption::FSName("CipherBox".to_string()), MountOption::DefaultPermissions, MountOption::RW];
212→    #[cfg(target_os = "macos")]
213→    let options = vec![
214→        MountOption::FSName("CipherBox".to_string()),
215→        MountOption::CUSTOM("volname=CipherBox".to_string()),
216→        MountOption::CUSTOM("noappledouble".to_string()),
217→        MountOption::CUSTOM("noapplexattr".to_string()),
218→        MountOption::CUSTOM("backend=smb".to_string()),
219→        MountOption::RW,
220→    ];
221→
222→    let (tx, rx) = std::sync::mpsc::sync_channel::<Result<(), String>>(1);
223→    let handle = std::thread::Builder::new()
224→        .name("fuse-mount".to_string())
225→        .spawn(move || {
226→            log::info!("Mounting CipherBoxFS at {}", mount_path_clone.display());
227→            match fuser::mount2(fs, &mount_path_clone, &options) {
228→                Ok(()) => { log::info!("FUSE filesystem unmounted cleanly"); let _ = tx.send(Ok(())); }
229→                Err(e) => { log::error!("FUSE mount error: {}", e); let _ = tx.send(Err(format!("FUSE mount error: {}", e))); }
230→            }
231→        })
232→        .map_err(|e| format!("Failed to spawn FUSE thread: {}", e))?;
233→
234→    match rx.recv_timeout(std::time::Duration::from_secs(2)) {
235→        Ok(Ok(())) => Err("FUSE filesystem unmounted immediately after mounting".to_string()),
236→        Ok(Err(e)) => Err(e),
237→        Err(std::sync::mpsc::RecvTimeoutError::Timeout) => { log::info!("FUSE mount confirmed at {}", mount_path.display()); Ok(handle) }
238→        Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => Err("FUSE mount thread exited unexpectedly".to_string()),
239→    }
240→}
