  1→//! Windows filesystem module for CipherBox Desktop.
  2→//!
  3→//! Provides WinFsp-based mount and unmount functions.
  4→//! The `operations` module implements the `FileSystemContext` trait.
  5→
  6→#[cfg(feature = "winfsp")]
  7→mod read_ops;
  8→#[cfg(feature = "winfsp")]
  9→mod write_ops;
 10→#[cfg(feature = "winfsp")]
 11→mod dir_ops;
 12→#[cfg(feature = "winfsp")]
 13→pub mod operations;
 14→
 15→#[cfg(feature = "winfsp")]
 16→mod mount_impl {
 17→    use std::collections::HashMap;
 18→    use std::sync::atomic::AtomicU64;
 19→    use std::sync::{Arc, Mutex};
 20→
 21→    use zeroize::Zeroizing;
 22→
 23→    use crate::fuse::{
 24→        cache, inode, CipherBoxFS, PendingContent, PendingRefresh, PublishCoordinator,
 25→        UploadComplete,
 26→    };
 27→    use crate::state::AppState;
 28→
 29→    /// Global handle to the WinFsp stop signal for clean shutdown.
 30→    /// Replaced on each mount so remount after unmount works correctly.
 31→    static WINFSP_STOP: Mutex<Option<Arc<std::sync::atomic::AtomicBool>>> = Mutex::new(None);
 32→
 33→    /// Mount the WinFsp filesystem after successful authentication.
 34→    ///
 35→    /// Creates the CipherBoxFS with keys from AppState, pre-populates the root
 36→    /// folder from IPNS, and spawns the WinFsp event loop on a dedicated thread.
 37→    ///
 38→    /// Returns a JoinHandle for the mount thread.
 39→    ///
 40→    /// Key differences from macOS mount:
 41→    /// - WinFsp creates the mount directory as a reparse point -- do NOT pre-create it
 42→    /// - No Spotlight suppression (Windows-specific)
 43→    /// - Uses WinFsp FileSystemHost instead of fuser::mount2
 44→    pub async fn mount_filesystem(
 45→        state: &AppState,
 46→        rt: tokio::runtime::Handle,
 47→        private_key: Vec<u8>,
 48→        public_key: Vec<u8>,
 49→        root_folder_key: Vec<u8>,
 50→        root_ipns_name: String,
 51→        root_ipns_private_key: Option<Vec<u8>>,
 52→        tee_public_key: Option<Vec<u8>>,
 53→        tee_key_epoch: Option<u32>,
 54→    ) -> Result<std::thread::JoinHandle<()>, String> {
 55→        let mount_path = crate::fuse::mount_point();
 56→
 57→        // WinFsp creates the mount directory as a reparse point.
 58→        // If a stale mount directory exists from a crash, clean it.
 59→        if mount_path.exists() {
 60→            match std::fs::remove_dir_all(&mount_path) {
 61→                Ok(()) => log::info!("Cleaned stale mount point: {}", mount_path.display()),
 62→                Err(e) => log::warn!("Failed to clean stale mount point {}: {}", mount_path.display(), e),
 63→            }
 64→        }
 65→
 66→        // Create temp directory for write buffering
 67→        let temp_dir = std::env::temp_dir().join("cipherbox");
 68→        std::fs::create_dir_all(&temp_dir)
 69→            .map_err(|e| format!("Failed to create temp directory: {}", e))?;
 70→
 71→        // Build the inode table
 72→        let mut inodes = inode::InodeTable::new();
 73→
 74→        // Set root inode's IPNS data
 75→        if let Some(root) = inodes.get_mut(inode::ROOT_INO) {
 76→            root.kind = inode::InodeKind::Root {
 77→                ipns_private_key: root_ipns_private_key.map(Zeroizing::new),
 78→                ipns_name: Some(root_ipns_name.clone()),
 79→            };
 80→        }
 81→
 82→        // Channels for background operations
 83→        let (refresh_tx, refresh_rx) = std::sync::mpsc::channel::<PendingRefresh>();
 84→        let (content_tx, content_rx) = std::sync::mpsc::channel::<PendingContent>();
 85→        let (upload_tx, upload_rx) = std::sync::mpsc::channel::<UploadComplete>();
 86→
 87→        // Pre-populate root folder BEFORE mounting so readdir has data immediately.
 88→        let mut metadata_cache = cache::MetadataCache::new();
 89→        log::info!("Pre-populating root folder from IPNS...");
 90→        let fetch_result: Result<(Vec<u8>, String), String> = async {
 91→            let resolve_resp =
 92→                cipherbox_api_client::ipns::resolve_ipns(&state.sdk.api, &root_ipns_name).await.map_err(|e| e.to_string())?;
 93→            let encrypted_bytes =
 94→                cipherbox_api_client::ipfs::fetch_content(&state.sdk.api, &resolve_resp.cid).await.map_err(|e| e.to_string())?;
 95→            Ok((encrypted_bytes, resolve_resp.cid))
 96→        }
 97→        .await;
 98→
 99→        match fetch_result {
100→            Ok((encrypted_bytes, cid)) => {
101→                match cipherbox_core::decrypt::decrypt_metadata_from_ipfs_public(&encrypted_bytes, &root_folder_key) {
102→                    Ok(metadata) => {
103→                        metadata_cache.set(&root_ipns_name, metadata.clone(), cid);
104→
105→                        match inodes.populate_folder(
106→                            inode::ROOT_INO,
107→                            &metadata,
108→                            &private_key,
109→                            &public_key,
110→                            false,
111→                        ) {
112→                            Ok(()) => {
113→                                log::info!("Root folder pre-populated successfully");
114→
115→                                // Resolve FilePointers eagerly before mount
116→                                let unresolved = inodes.get_unresolved_file_pointers();
117→                                if !unresolved.is_empty() {
118→                                    log::info!(
119→                                        "Resolving {} root FilePointer(s)...",
120→                                        unresolved.len()
121→                                    );
122→                                    let root_folder_key_arr: Result<[u8; 32], _> =
123→                                        root_folder_key.as_slice().try_into();
124→                                    if let Ok(fk) = root_folder_key_arr {
125→                                        for (fp_ino, fp_ipns) in &unresolved {
126→                                            let fp_result: Result<Vec<u8>, String> = async {
127→                                                let resp = cipherbox_api_client::ipns::resolve_ipns(
128→                                                    &state.sdk.api,
129→                                                    fp_ipns,
130→                                                )
131→                                                .await?;
132→                                                let bytes = cipherbox_api_client::ipfs::fetch_content(
133→                                                    &state.sdk.api,
134→                                                    &resp.cid,
135→                                                )
136→                                                .await?;
137→                                                Ok(bytes)
138→                                            }
139→                                            .await;
140→                                            match fp_result {
141→                                                Ok(enc_bytes) => {
142→                                                    match cipherbox_core::decrypt::decrypt_file_metadata_from_ipfs_public(
143→                                                        &enc_bytes, &fk,
144→                                                    ) {
145→                                                        Ok(fm) => {
146→                                                            inodes.resolve_file_pointer(
147→                                                                *fp_ino,
148→                                                                fm.cid,
149→                                                                fm.file_key_encrypted,
150→                                                                fm.file_iv,
151→                                                                fm.size,
152→                                                                fm.encryption_mode,
153→                                                                fm.versions,
154→                                                            );
155→                                                        }
156→                                                        Err(e) => log::warn!(
157→                                                            "Root FilePointer decrypt failed for ino {}: {}",
158→                                                            fp_ino,
159→                                                            e
160→                                                        ),
161→                                                    }
162→                                                }
163→                                                Err(e) => log::warn!(
164→                                                    "Root FilePointer resolve failed for ino {}: {}",
165→                                                    fp_ino,
166→                                                    e
167→                                                ),
168→                                            }
169→                                        }
170→                                    }
171→                                }
172→
173→                                // Pre-populate immediate subfolders
174→                                let subfolder_infos: Vec<(u64, String, Zeroizing<Vec<u8>>)> =
175→                                    inodes
176→                                        .inodes
177→                                        .values()
178→                                        .filter_map(|inode| {
179→                                            if inode.parent_ino != inode::ROOT_INO {
180→                                                return None;
181→                                            }
182→                                            if let inode::InodeKind::Folder {
183→                                                ref ipns_name,
184→                                                ref folder_key,
185→                                                ..
186→                                            } = inode.kind
187→                                            {
188→                                                Some((
189→                                                    inode.ino,
190→                                                    ipns_name.clone(),
191→                                                    folder_key.clone(),
192→                                                ))
193→                                            } else {
194→                                                None
195→                                            }
196→                                        })
197→                                        .collect();
198→
199→                                for (sub_ino, sub_ipns, sub_key) in &subfolder_infos {
200→                                    log::info!(
201→                                        "Pre-populating subfolder ino={} ipns={}",
202→                                        sub_ino,
203→                                        sub_ipns
204→                                    );
205→                                    let sub_result: Result<(Vec<u8>, String), String> = async {
206→                                        let resp =
207→                                            cipherbox_api_client::ipns::resolve_ipns(&state.sdk.api, sub_ipns)
208→                                                .await?;
209→                                        let bytes = cipherbox_api_client::ipfs::fetch_content(
210→                                            &state.sdk.api,
211→                                            &resp.cid,
212→                                        )
213→                                        .await?;
214→                                        Ok((bytes, resp.cid))
215→                                    }
216→                                    .await;
217→                                    match sub_result {
218→                                        Ok((enc_bytes, sub_cid)) => {
219→                                            match cipherbox_core::decrypt::decrypt_metadata_from_ipfs_public(&enc_bytes, sub_key) {
220→                                                Ok(sub_metadata) => {
221→                                                    metadata_cache.set(
222→                                                        sub_ipns,
223→                                                        sub_metadata.clone(),
224→                                                        sub_cid,
225→                                                    );
226→                                                    match inodes.populate_folder(
227→                                                        *sub_ino,
228→                                                        &sub_metadata,
229→                                                        &private_key,
230→                                                        &public_key,
231→                                                        false,
232→                                                    ) {
233→                                                        Ok(()) => {
234→                                                            log::info!(
235→                                                                "Subfolder ino={} pre-populated",
236→                                                                sub_ino
237→                                                            );
238→                                                            let sub_unresolved =
239→                                                                inodes.get_unresolved_file_pointers_for_parent(*sub_ino);
240→                                                            if !sub_unresolved.is_empty() {
241→                                                                let sk_arr: Result<[u8; 32], _> =
242→                                                                    sub_key.as_slice().try_into();
243→                                                                if let Ok(sk) = sk_arr {
244→                                                                    for (fp_ino, fp_ipns) in
245→                                                                        &sub_unresolved
246→                                                                    {
247→                                                                        let fp_result: Result<
248→                                                                            Vec<u8>,
249→                                                                            String,
250→                                                                        > = async {
251→                                                                            let resp =
252→                                                                                cipherbox_api_client::ipns::resolve_ipns(
253→                                                                                    &state.sdk.api,
254→                                                                                    fp_ipns,
255→                                                                                )
256→                                                                                .await?;
257→                                                                            let bytes =
258→                                                                                cipherbox_api_client::ipfs::fetch_content(
259→                                                                                    &state.sdk.api,
260→                                                                                    &resp.cid,
261→                                                                                )
262→                                                                                .await?;
263→                                                                            Ok(bytes)
264→                                                                        }
265→                                                                        .await;
266→                                                                        match fp_result {
267→                                                                            Ok(enc_bytes) => {
268→                                                                                match cipherbox_core::decrypt::decrypt_file_metadata_from_ipfs_public(&enc_bytes, &sk) {
269→                                                                                    Ok(fm) => {
270→                                                                                        inodes.resolve_file_pointer(
271→                                                                                            *fp_ino,
272→                                                                                            fm.cid,
273→                                                                                            fm.file_key_encrypted,
274→                                                                                            fm.file_iv,
275→                                                                                            fm.size,
276→                                                                                            fm.encryption_mode,
277→                                                                                            fm.versions,
278→                                                                                        );
279→                                                                                    }
280→                                                                                    Err(e) => log::warn!(
281→                                                                                        "Sub FilePointer decrypt failed: {}",
282→                                                                                        e
283→                                                                                    ),
284→                                                                                }
285→                                                                            }
286→                                                                            Err(e) => log::warn!(
287→                                                                                "Sub FilePointer resolve failed: {}",
288→                                                                                e
289→                                                                            ),
290→                                                                        }
291→                                                                    }
292→                                                                }
293→                                                            }
294→                                                        }
295→                                                        Err(e) => log::warn!(
296→                                                            "Subfolder ino={} populate failed: {}",
297→                                                            sub_ino,
298→                                                            e
299→                                                        ),
300→                                                    }
301→                                                }
302→                                                Err(e) => log::warn!(
303→                                                    "Subfolder ino={} decrypt failed: {}",
304→                                                    sub_ino,
305→                                                    e
306→                                                ),
307→                                            }
308→                                        }
309→                                        Err(e) => log::warn!(
310→                                            "Subfolder ino={} fetch failed: {}",
311→                                            sub_ino,
312→                                            e
313→                                        ),
314→                                    }
315→                                }
316→                            }
317→                            Err(e) => log::warn!("Root folder populate failed: {}", e),
318→                        }
319→                    }
320→                    Err(e) => log::warn!("Root metadata decryption failed: {}", e),
321→                }
322→            }
323→            Err(e) => {
324→                log::warn!("Root folder fetch failed (mount will show empty): {}", e)
325→            }
326→        }
327→
328→        let fs = CipherBoxFS {
329→            inodes,
330→            metadata_cache,
331→            content_cache: cache::ContentCache::new(),
332→            api: state.sdk.api.clone(),
333→            private_key: Zeroizing::new(private_key),
334→            public_key: Zeroizing::new(public_key),
335→            root_folder_key: Zeroizing::new(root_folder_key),
336→            root_ipns_name,
337→            rt: rt.clone(),
338→            next_fh: AtomicU64::new(1),
339→            open_files: HashMap::new(),
340→            temp_dir,
341→            tee_public_key,
342→            tee_key_epoch,
343→            refresh_rx,
344→            refresh_tx,
345→            prefetching: std::collections::HashSet::new(),
346→            content_rx,
347→            content_tx,
348→            pending_content: HashMap::new(),
349→            upload_rx,
350→            upload_tx,
351→            mutated_folders: HashMap::new(),
352→            publish_coordinator: Arc::new(PublishCoordinator::new()),
353→            publish_queue: HashMap::new(),
354→        };
355→
356→        // Create WinFsp context with Arc<Mutex<>> for interior mutability
357→        let context = super::operations::implementation::WinFspContext {
358→            inner: Arc::new(Mutex::new(fs)),
359→            rt: rt.clone(),
360→        };
361→
362→        // Initialize WinFsp runtime
363→        // NOTE: winfsp_init_or_die() calls std::process::exit() on failure,
364→        // killing the process silently. Use winfsp_init() instead for proper error handling.
365→        log::info!("Initializing WinFsp runtime...");
366→        let _init = winfsp::winfsp_init()
367→            .map_err(|e| format!("WinFsp initialization failed (is WinFsp installed?): {:?}", e))?;
368→        log::info!("WinFsp runtime initialized successfully");
369→
370→        // Create volume params
371→        log::info!("Creating WinFsp volume params...");
372→        let mut volume_params = winfsp::host::VolumeParams::new();
373→        volume_params
374→            .filesystem_name("CipherBox")
375→            .file_info_timeout(1000) // 1s attribute cache
376→            .case_sensitive_search(false) // Windows convention
377→            .case_preserved_names(true);
378→
379→        log::info!("Creating WinFsp FileSystemHost...");
380→        let mut host = winfsp::host::FileSystemHost::new(
381→            volume_params,
382→            context,
383→        )
384→        .map_err(|e| format!("Failed to create WinFsp host: {:?}", e))?;
385→        log::info!("WinFsp FileSystemHost created");
386→
387→        // Set mount point
388→        let mount_str = mount_path
389→            .to_str()
390→            .ok_or("Mount path is not valid UTF-8")?
391→            .to_string();
392→        log::info!("Mounting WinFsp at {}...", mount_str);
393→        host.mount(&mount_str)
394→            .map_err(|e| format!("Failed to set WinFsp mount point: {:?}", e))?;
395→        log::info!("WinFsp mount point set successfully");
396→
397→        // Set up stop signal for clean shutdown (replaced on each mount for remount support)
398→        let stop_signal = Arc::new(std::sync::atomic::AtomicBool::new(false));
399→        *WINFSP_STOP.lock().unwrap() = Some(stop_signal.clone());
400→        let stop_clone = stop_signal.clone();
401→
402→        // Start the dispatcher and spawn a keep-alive thread.
403→        //
404→        // FspFileSystemStartDispatcher starts background worker threads and
405→        // returns immediately (it does NOT block). The FileSystemHost must
406→        // remain alive for the mounted filesystem to keep working — dropping
407→        // it calls FspFileSystemStopDispatcher + FspFileSystemRemoveMountPoint.
408→        //
409→        // The dedicated thread holds ownership of `host` and parks until the
410→        // stop signal fires, at which point it drops the host (clean shutdown).
411→        let (tx, rx) = std::sync::mpsc::sync_channel::<Result<(), String>>(1);
412→
413→        let handle = std::thread::Builder::new()
414→            .name("winfsp-mount".to_string())
415→            .spawn(move || {
416→                log::info!("WinFsp filesystem starting at {}", mount_str);
417→                match host.start() {
418→                    Ok(()) => {
419→                        // Dispatcher threads started — filesystem is live.
420→                        log::info!("WinFsp dispatcher started at {}", mount_str);
421→                        let _ = tx.send(Ok(()));
422→
423→                        // Keep host alive until stop is signaled.
424→                        while !stop_clone.load(std::sync::atomic::Ordering::SeqCst) {
425→                            std::thread::sleep(std::time::Duration::from_millis(200));
426→                        }
427→                        log::info!("WinFsp stop signal received, shutting down...");
428→                        // host.stop() + host.unmount() happen in Drop
429→                    }
430→                    Err(e) => {
431→                        log::error!("WinFsp start error: {:?}", e);
432→                        let _ = tx.send(Err(format!("WinFsp start error: {:?}", e)));
433→                    }
434→                }
435→            })
436→            .map_err(|e| format!("Failed to spawn WinFsp thread: {}", e))?;
437→
438→        // Wait for the start() result (should arrive almost immediately)
439→        match rx.recv_timeout(std::time::Duration::from_secs(5)) {
440→            Ok(Ok(())) => {
441→                // Dispatcher started, mount is live
442→                log::info!("WinFsp mount confirmed at {}", mount_path.display());
443→                Ok(handle)
444→            }
445→            Ok(Err(e)) => {
446→                // start() returned an error
447→                Err(e)
448→            }
449→            Err(std::sync::mpsc::RecvTimeoutError::Timeout) => {
450→                Err("WinFsp dispatcher start timed out".to_string())
451→            }
452→            Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => {
453→                Err("WinFsp mount thread exited unexpectedly".to_string())
454→            }
455→        }
456→    }
457→
458→    /// Unmount the WinFsp filesystem.
459→    ///
460→    /// Sets the stop signal which causes the mount keep-alive thread to exit.
461→    /// When the thread exits, the FileSystemHost is dropped, which calls
462→    /// FspFileSystemStopDispatcher() + FspFileSystemRemoveMountPoint().
463→    ///
464→    /// Also cleans up the temp directory and stale mount point.
465→    pub fn unmount_filesystem() -> Result<(), String> {
466→        let mount_path = crate::fuse::mount_point();
467→        log::info!("Unmounting WinFsp at {}", mount_path.display());
468→
469→        // Signal the stop flag for the current mount's keep-alive thread
470→        if let Some(stop) = WINFSP_STOP.lock().unwrap().as_ref() {
471→            stop.store(true, std::sync::atomic::Ordering::SeqCst);
472→        }
473→
474→        // Clean up temp directory
475→        let temp_dir = std::env::temp_dir().join("cipherbox");
476→        if temp_dir.exists() {
477→            if let Err(e) = std::fs::remove_dir_all(&temp_dir) {
478→                log::warn!("Failed to clean temp directory: {}", e);
479→            }
480→        }
481→
482→        // WinFsp removes the reparse point mount directory on clean shutdown.
483→        // If it's still there after a crash, clean it up.
484→        if mount_path.exists() {
485→            if let Err(e) = std::fs::remove_dir_all(&mount_path) {
486→                log::warn!("Failed to remove stale mount path {}: {}", mount_path.display(), e);
487→            }
488→        }
489→
490→        log::info!("WinFsp unmount cleanup complete");
491→        Ok(())
492→    }
493→}
