 40→    /// Key differences from macOS mount:
 41→    /// - WinFsp creates the mount directory as a reparse point -- do NOT pre-create it
 42→    /// - No Spotlight suppression (Windows-specific)
 43→    /// - Uses WinFsp FileSystemHost instead of fuser::mount2
 44→    pub async fn mount_filesystem(
 45→        state: &AppState,
 46→        rt: tokio::runtime::Handle,
 47→        private_key: Vec<u8>,
 48→        public_key: Vec<u8>,
 49→        root_folder_key: Vec<u8>,
