 54→    ) -> Result<std::thread::JoinHandle<()>, String> {
 55→        let mount_path = crate::fuse::mount_point();
 56→
 57→        // WinFsp creates the mount directory as a reparse point.
 58→        // If a stale mount directory exists from a crash, clean it.
 59→        if mount_path.exists() {
 60→            match std::fs::remove_dir_all(&mount_path) {
 61→                Ok(()) => log::info!("Cleaned stale mount point: {}", mount_path.display()),
 62→                Err(e) => log::warn!("Failed to clean stale mount point {}: {}", mount_path.display(), e),
 63→            }
 64→        }
 65→
 66→        // Create temp directory for write buffering
 67→        let temp_dir = std::env::temp_dir().join("cipherbox");
 68→        std::fs::create_dir_all(&temp_dir)
 69→            .map_err(|e| format!("Failed to create temp directory: {}", e))?;
 70→
 71→        // Build the inode table
 72→        let mut inodes = inode::InodeTable::new();
 73→
 74→        // Set root inode's IPNS data
 75→        if let Some(root) = inodes.get_mut(inode::ROOT_INO) {
 76→            root.kind = inode::InodeKind::Root {
 77→                ipns_private_key: root_ipns_private_key.map(Zeroizing::new),
 78→                ipns_name: Some(root_ipns_name.clone()),
 79→            };
 80→        }
 81→
 82→        // Channels for background operations
 83→        let (refresh_tx, refresh_rx) = std::sync::mpsc::channel::<PendingRefresh>();
 84→        let (content_tx, content_rx) = std::sync::mpsc::channel::<PendingContent>();
 85→        let (upload_tx, upload_rx) = std::sync::mpsc::channel::<UploadComplete>();
 86→
