199→                                for (sub_ino, sub_ipns, sub_key) in &subfolder_infos {
200→                                    log::info!(
201→                                        "Pre-populating subfolder ino={} ipns={}",
202→                                        sub_ino,
203→                                        sub_ipns
204→                                    );
205→                                    let sub_result: Result<(Vec<u8>, String), String> = async {
206→                                        let resp =
207→                                            cipherbox_api_client::ipns::resolve_ipns(&state.sdk.api, sub_ipns)
208→                                                .await?;
